export const CARDS = {
  wset1: [
    { id:1, category:"Grapes & Varieties", q:"What are the two main grape colours used in winemaking?", a:"Black grapes and white grapes. Black (dark-skinned) grapes make red and rosé wines; white (green/yellow-skinned) grapes make white wines. White wine can also be made from black grapes by pressing them before the skins colour the juice.", ref:null },
    { id:2, category:"Grapes & Varieties", q:"Name 3 common white grape varieties.", a:"Chardonnay, Sauvignon Blanc, Riesling.", ref:{ type:"map", label:"White wine regions map", url:"https://www.winespectator.com/images/site/learn/maps/france_map_lg.gif" } },
    { id:3, category:"Grapes & Varieties", q:"Name 3 common red grape varieties.", a:"Cabernet Sauvignon, Merlot, Pinot Noir.", ref:{ type:"search", label:"Search bottles", url:"https://www.wine-searcher.com/find/cabernet+sauvignon" } },
    { id:4, category:"Vinification", q:"What is the basic process of making white wine?", a:"Harvest → Crush/Press → Fermentation (no skin contact) → Clarification → Stabilization → Bottling.", ref:null },
    { id:5, category:"Vinification", q:"Why does red wine have more tannin than white?", a:"Because red wine undergoes skin-contact maceration during fermentation, extracting tannins from grape skins, seeds, and stems.", ref:null },
    { id:6, category:"Tasting", q:"What are the main structural elements you assess on the palate?", a:"Sweetness, acidity, tannin (mainly in reds), alcohol and body. Sweetness and acidity are true tastes; tannin is a drying texture, alcohol is a warming sensation, and together they shape the wine's body.", ref:null },
    { id:7, category:"Service & Pairing", q:"At what temperature should red wine generally be served?", a:"16–18°C (61–64°F) — lighter reds slightly cooler at 12–14°C.", ref:null },
    { id:8, category:"Service & Pairing", q:"What is the classic pairing rule for white wine and food?", a:"White wine generally pairs best with lighter dishes: fish, shellfish, poultry, and cream-based sauces.", ref:null },
    { id:9, category:"Viticulture", q:"What does a grapevine need to grow and ripen fruit?", a:"Sunlight (for photosynthesis and ripening), warmth (minimum 10°C growing season), water (moderate rainfall or irrigation), and well-drained soil.", ref:null },
    { id:10, category:"Viticulture", q:"What is the difference between warm and cool climate wines?", a:"Cool climates produce wines with higher acidity, lower alcohol, and lighter fruit flavors (green apple, lemon). Warm climates yield wines with lower acidity, higher alcohol, and riper fruit (tropical, dark berry).", ref:null },
    { id:11, category:"Grapes & Varieties", q:"What is Rosé wine and how is it made?", a:"Rosé is made from red grapes with brief skin contact (a few hours to 2 days), giving a pink color without full red wine extraction. It can also be made by blending red and white wine (mainly in Champagne).", ref:null },
    { id:12, category:"Vinification", q:"What is fermentation?", a:"The process by which yeast converts the natural sugars in grape juice into alcohol and carbon dioxide. This is what turns grape juice into wine.", ref:null },
    { id:13, category:"Vinification", q:"What does 'dry' mean when describing a wine?", a:"A dry wine has little to no residual sugar — all or nearly all the grape sugar has been converted to alcohol during fermentation. The opposite is sweet or off-dry.", ref:null },
    { id:14, category:"Tasting", q:"What causes a wine to taste acidic or tart?", a:"Natural fruit acids (primarily tartaric, malic, and citric acid) present in the grapes. Acidity makes wine taste fresh, crisp, and food-friendly. It is a key structural element.", ref:null },
    { id:15, category:"Service & Pairing", q:"How should white and sparkling wines be stored before service?", a:"They should be chilled: whites at 8–12°C (46–54°F), sparkling wines at 6–8°C (42–46°F). Store on their side if corked to keep the cork moist.", ref:null },
    { id:16, category:"Labels & Law", q:"What information is typically found on a wine label?", a:"Producer name, wine name or grape variety, region/appellation of origin, vintage year, alcohol percentage, country of origin, and volume. Quality classification may also appear.", ref:null },
    { id:17, category:"Grapes & Varieties", q:"What is Champagne and where does it come from?", a:"Champagne is a sparkling wine produced exclusively in the Champagne region of northeastern France, primarily from Chardonnay, Pinot Noir, and Pinot Meunier grapes.", ref:{ type:"map", label:"Champagne region map", url:"https://www.champagne.fr/en/champagne-vineyard/champagne-viticultural-zones/map" } },
    { id:18, category:"Tasting", q:"What is 'body' in wine?", a:"Body refers to the weight and fullness of wine in the mouth, often influenced by alcohol level and extract. Light-bodied wines feel like water; full-bodied wines feel like whole milk. Alcohol is the primary driver.", ref:null },
    { id:19, category:"Service & Pairing", q:"What is the correct way to hold a wine glass?", a:"Hold by the stem, not the bowl. This prevents warming the wine with body heat, avoids fingerprints on the bowl (obscuring color assessment), and looks professional. For tasting/evaluation, always hold by the stem or base.", ref:null },
    { id:20, category:"Grapes & Varieties", q:"What is the difference between a grape variety and a wine style?", a:"A grape variety is the type of grape (Chardonnay, Cabernet Sauvignon). A wine style describes how the wine tastes and is made (oaked/unoaked, dry/sweet, still/sparkling). The same grape can produce many different wine styles depending on region and winemaking choices.", ref:null },
    { id:21, category:"Vinification", q:"What is the basic process of making red wine?", a:"Harvest → De-stem/Crush → Fermentation WITH skin contact (maceration extracts color and tannin) → Press → Malolactic fermentation (usually) → Aging in oak or tank → Clarification → Bottling.", ref:null },
    { id:22, category:"Regions", q:"Name 3 major wine-producing countries of the New World.", a:"United States (California, Oregon, Washington), Australia (Barossa, Margaret River, Yarra Valley), and Argentina (Mendoza, Patagonia). Others include Chile, New Zealand, and South Africa.", ref:{ type:"map", label:"New World wine regions", url:"https://winefolly.com/learn/wine-region-maps/" } },
    { id:23, category:"Tasting", q:"What does 'tannic' mean when describing a red wine?", a:"Tannins are naturally occurring compounds from grape skins, seeds, and stems (and oak). They create a drying, grippy, or astringent sensation in the mouth — like strong black tea. High-tannin grapes: Cabernet Sauvignon, Nebbiolo, Syrah. Low-tannin grapes: Pinot Noir, Gamay.", ref:null },
    { id:24, category:"Regions", q:"What country produces Rioja, and what grape is it famous for?", a:"Spain. Rioja is one of Spain's most celebrated wine regions, famous for wines made primarily from Tempranillo, often blended with Garnacha, Mazuelo, and Graciano. Wines range from young (Joven) to very aged (Gran Reserva).", ref:{ type:"map", label:"Rioja wine map", url:"https://www.wine-searcher.com/regions/rioja" } },
    { id:25, category:"Vinification", q:"What is the difference between oaked and unoaked wine?", a:"Oaked wine is fermented or aged in oak barrels, gaining vanilla, spice, toast, and cedar flavors with a rounder, creamier texture. Unoaked wine is made in stainless steel or neutral vessels, preserving fresh fruit, higher acidity, and a cleaner, crisper style. Example: oaked Chardonnay (Meursault) vs. unoaked (Chablis).", ref:null },
    { id:26, category:"Tasting", q:"What does 'aroma' mean in wine tasting?", a:"Aroma refers to the scents detected in a wine by smelling the glass. Aromas come from the grape variety (fruity, floral, herbal), fermentation (yeasty, creamy), and aging (earthy, spicy, leathery). Swirling the glass releases volatile aromatic compounds, making them easier to detect.", ref:null },
    { id:27, category:"Service & Pairing", q:"What foods pair well with red wine?", a:"Red wine generally pairs best with red meat (steak, lamb, venison), hard aged cheeses, mushroom-based dishes, and tomato-based pasta. The tannins in red wine are softened by the protein and fat in meat, making the pairing mutually enhancing.", ref:null },
    { id:28, category:"Grapes & Varieties", q:"What is Merlot and what does it taste like?", a:"Merlot is a soft, round red grape variety producing wines with plum, black cherry, chocolate, and mocha flavors. It has lower tannins and softer acidity than Cabernet Sauvignon, making it approachable young. Key regions: Pomerol and Saint-Émilion (France), California, Washington State, Chile.", ref:{ type:"search", label:"Merlot bottles", url:"https://www.wine-searcher.com/find/merlot" } },
    { id:29, category:"Regions", q:"Where does Champagne come from and what makes it special?", a:"Champagne comes exclusively from the Champagne region of northeastern France. What makes it special: its cool climate preserves high acidity ideal for sparkling wine, its unique chalk soils give finesse, and the traditional method (secondary fermentation in bottle) creates fine, persistent bubbles and complex yeasty flavors.", ref:{ type:"map", label:"Champagne region", url:"https://www.champagne.fr/en/champagne-vineyard/champagne-viticultural-zones/map" } },
    { id:30, category:"Tasting", q:"What does it mean when a wine is described as 'dry', 'off-dry', or 'sweet'?", a:"Dry: virtually no residual sugar (most table wines). Off-dry: slight sweetness noticeable but not dominant (many Rieslings, Vouvray). Medium-sweet: clearly sweet (Spätlese, some Chenin Blanc). Sweet: very noticeable sweetness (Sauternes, late harvest wines). The perception of sweetness in wine comes from residual sugar left after fermentation.", ref:null },
    { id:31, category:"Grapes & Varieties", q:"What is Pinot Grigio and why is it so popular?", a:"Pinot Grigio is a light, crisp, dry Italian white wine made from the Pinot Gris grape. It is popular for its easy-drinking style — low tannin, refreshing acidity, mild pear and citrus flavors — and food-friendly versatility. Key regions: Veneto, Trentino-Alto Adige, Friuli. It is one of the world's best-selling white wines.", ref:{ type:"search", label:"Pinot Grigio bottles", url:"https://www.wine-searcher.com/find/pinot+grigio" } },
    { id:32, category:"Viticulture", q:"What is a 'vintage' and does it matter?", a:"A vintage is the year the grapes were harvested. It matters because weather varies year to year — a warm, dry year produces riper, richer wines while a cool, wet year may produce lighter, more acidic wines or even affect quality negatively. In stable climates (California, Australia), vintage variation is less dramatic than in marginal climates (Burgundy, Champagne, Germany).", ref:null },
    { id:33, category:"Service & Pairing", q:"What is a wine 'flight' and how is it typically organized?", a:"A wine flight is a curated selection of multiple wines served together for tasting and comparison. Flights are typically organized by: region (e.g., three Burgundy Pinot Noirs), variety (e.g., Chardonnays from around the world), or style (e.g., dry to sweet). They allow side-by-side comparison and are common in restaurants, wine bars, and educational settings.", ref:null },
    { id:34, category:"Vinification", q:"What is the difference between sparkling wine made by the traditional method versus the tank method?", a:"Traditional method (Champagne, Cava, Franciacorta): secondary fermentation happens in the bottle, creating fine persistent bubbles and complex yeasty/bready flavors from extended lees contact. Tank method (Charmat/Prosecco): secondary fermentation in a pressurized tank, producing fresher, fruitier wine with larger bubbles. Traditional method is more expensive and complex.", ref:null },
    { id:35, category:"Service & Pairing", q:"Why is it important to smell wine before tasting it?", a:"About 80% of flavor perception comes from the sense of smell (retronasal olfaction). Smelling the wine first lets you assess its condition (is it faulty?), identify aromas (fruit, oak, earth), and prepare your palate. Swirl the glass gently to release volatile aromatic compounds before smelling.", ref:null },
    { id:36, category:"Grapes & Varieties", q:"What is Syrah (also called Shiraz) and where is it grown?", a:"Syrah is a full-bodied, deeply colored red grape. In France's Northern Rhône (Hermitage, Crozes-Hermitage): savory, peppery, smoky. As Shiraz in Australia (Barossa Valley): richer, riper, with blackberry, chocolate, and licorice. Also important in South Africa, California, and Washington State.", ref:{ type:"search", label:"Syrah/Shiraz bottles", url:"https://www.wine-searcher.com/find/syrah+shiraz" } },
    { id:37, category:"Regions", q:"What country is famous for Port wine?", a:"Portugal. Port is a fortified wine produced exclusively in the Douro Valley, Portugal. Grape spirit is added during fermentation to stop it early, leaving residual sugar and raising alcohol to 19–22%. Styles include Ruby, Tawny, LBV, and Vintage Port. It is typically served as a dessert wine.", ref:{ type:"map", label:"Douro Valley map", url:"https://www.wine-searcher.com/regions/douro" } },
    { id:38, category:"Tasting", q:"What does 'complexity' mean in wine?", a:"A complex wine has many different layers of aromas and flavors that evolve and change as you smell and taste it — rather than showing just one or two simple notes. Complexity develops through great terroir, aging, and skilled winemaking. It is one of the key markers of a high-quality wine.", ref:null },
  ],
  wset2: [
    { id:101, category:"Regions", q:"What are the 5 major wine-producing countries of the Old World?", a:"France, Italy, Spain, Germany, Portugal.", ref:{ type:"map", label:"Old World wine map", url:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Wine_regions_of_Europe.png/1200px-Wine_regions_of_Europe.png" } },
    { id:102, category:"Regions", q:"What are the key wine regions of Bordeaux?", a:"Left Bank: Médoc (Cabernet Sauvignon dominant). Right Bank: Pomerol and Saint-Émilion (Merlot dominant). Also Entre-Deux-Mers for whites.", ref:{ type:"map", label:"Bordeaux map", url:"https://www.wine-searcher.com/regions/bordeaux" } },
    { id:103, category:"Grapes & Varieties", q:"What grape is Burgundy's white wine made from?", a:"Chardonnay — unoaked styles in Chablis, richer oaked styles in Côte de Beaune (e.g., Meursault, Puligny-Montrachet).", ref:{ type:"map", label:"Burgundy map", url:"https://www.decanter.com/wp-content/uploads/2017/05/burgundy-map.jpg" } },
    { id:104, category:"Viticulture", q:"What is the difference between Old World and New World wine styles?", a:"Old World (Europe): higher acidity, lower alcohol, more earthy/savory. New World (Americas, Aus, NZ, SA): riper fruit, higher alcohol, more fruit-forward.", ref:null },
    { id:105, category:"Vinification", q:"What is malolactic fermentation (MLF)?", a:"Conversion of sharp malic acid into softer lactic acid by bacteria. Reduces acidity and adds buttery/creamy texture. Common in Chardonnay and most reds.", ref:null },
    { id:106, category:"Vinification", q:"What does oak aging add to wine?", a:"Vanilla, spice, toast, and coconut aromas. Oxygen contact through pores softens tannins. Adds complexity and structure.", ref:null },
    { id:107, category:"Labels & Law", q:"What does AOC mean on a French wine label?", a:"Appellation d'Origine Contrôlée — the highest classification indicating protected geographic origin with strict regulations on grape varieties, yields, and methods.", ref:null },
    { id:108, category:"Tasting", q:"Describe the WSET Level 2 Systematic Approach to Tasting (SAT) structure.", a:"Appearance (clarity, intensity, color) → Nose (condition, intensity, aromas) → Palate (sweetness, acidity, tannin, alcohol, body, intensity, finish) → Conclusions (quality, readiness).", ref:null },
    { id:109, category:"Regions", q:"Name the main wine regions of Italy and their signature grape or wine.", a:"Piedmont (Nebbiolo/Barolo), Tuscany (Sangiovese/Chianti, Brunello), Veneto (Garganega/Soave, Corvina/Amarone), Sicily (Nero d'Avola), and Friuli-Venezia Giulia (whites: Pinot Grigio, Friulano).", ref:{ type:"map", label:"Italy wine map", url:"https://www.wine-searcher.com/regions/italy" } },
    { id:110, category:"Regions", q:"What are the key wine regions and grapes of Spain?", a:"Rioja (Tempranillo), Ribera del Duero (Tempranillo/Tinto Fino), Priorat (Garnacha/Cariñena), Rías Baixas (Albariño), Jerez (Palomino/Sherry), Cava (Macabeo, Parellada, Xarel·lo).", ref:{ type:"map", label:"Spain wine map", url:"https://www.wine-searcher.com/regions/spain" } },
    { id:111, category:"Grapes & Varieties", q:"What are the characteristics of Sauvignon Blanc?", a:"High acidity, medium-light body, herbaceous aromas (grass, green pepper), citrus (grapefruit, lime), and often a distinctive passion fruit note. Key regions: Loire Valley (Sancerre, Pouilly-Fumé), Marlborough NZ.", ref:{ type:"search", label:"Sauvignon Blanc bottles", url:"https://www.wine-searcher.com/find/sauvignon+blanc" } },
    { id:112, category:"Viticulture", q:"What is the purpose of pruning a grapevine?", a:"Pruning in winter controls the yield (number of grape clusters) and shapes the vine for the coming season. It concentrates the vine's energy into fewer, higher-quality bunches and manages vine vigor.", ref:null },
    { id:113, category:"Viticulture", q:"What is phylloxera and why does it matter?", a:"Phylloxera is a root-feeding aphid that devastated European vineyards in the late 19th century. The solution was grafting Vitis vinifera vines onto resistant American rootstocks, still the standard practice worldwide today.", ref:null },
    { id:114, category:"Vinification", q:"What is the difference between a still, sparkling, and fortified wine?", a:"Still: no significant CO2, 8–15% alcohol. Sparkling: CO2 from secondary fermentation (Champagne, Prosecco, Cava). Fortified: grape spirit added during or after fermentation (Port, Sherry, Madeira), raising alcohol to 15–22%.", ref:null },
    { id:115, category:"Service & Pairing", q:"What are the main wine faults to detect in service?", a:"Cork taint (TCA) — damp cardboard/musty smell. Oxidation — flat, bruised apple. Reduction — struck match, rubber. Volatile acidity (VA) — vinegar. Refermentation — unexpected bubbles in still wine.", ref:null },
    { id:116, category:"Labels & Law", q:"What does Reserva mean on a Spanish wine label?", a:"Reserva wines must meet minimum aging requirements: red Rioja Reserva requires minimum 3 years aging with 1 year in oak. It indicates a producer's mid-tier selection, above Crianza but below Gran Reserva.", ref:{ type:"search", label:"Rioja Reserva bottles", url:"https://www.wine-searcher.com/find/rioja+reserva" } },
    { id:117, category:"Tasting", q:"How do you evaluate a wine's finish or length?", a:"The finish is the persistence of flavors after swallowing. Short: under 5 seconds. Medium: 5–10 seconds. Long: 10+ seconds. A long, complex finish is a hallmark of quality wine.", ref:null },
    { id:118, category:"Grapes & Varieties", q:"Describe the key characteristics of Pinot Grigio vs. Pinot Gris.", a:"Same grape, different styles. Italian Pinot Grigio: light, crisp, neutral, easy-drinking (Veneto, Trentino). Alsatian Pinot Gris: rich, full-bodied, spicy, often off-dry to sweet — more weight and complexity.", ref:null },
    { id:119, category:"Regions", q:"What is Prosecco and where is it made?", a:"Prosecco is an Italian sparkling wine made primarily from the Glera grape in the Veneto and Friuli regions of northeastern Italy. Key appellations: Prosecco DOC, Conegliano Valdobbiadene DOCG, Asolo DOCG. Made by the Charmat (tank) method — fresh, fruity, and lower in cost than Champagne.", ref:{ type:"map", label:"Prosecco region map", url:"https://www.wine-searcher.com/regions/prosecco" } },
    { id:120, category:"Viticulture", q:"What is the growing season of a grapevine in the Northern Hemisphere?", a:"Bud break: March–April. Flowering: May–June. Véraison (color change/ripening onset): July–August. Harvest: August–October depending on variety and climate. Dormancy: November–February. Southern Hemisphere seasons are reversed (harvest: February–April).", ref:null },
    { id:121, category:"Tasting", q:"What are the primary aroma categories used in WSET tasting notes?", a:"Fruit (fresh, dried, cooked/jammy). Floral (rose, violet, blossom). Spice (black pepper, cinnamon, clove). Herbal/vegetal (grass, eucalyptus, bell pepper). Oak-derived (vanilla, toast, cedar, coconut). Earth/mineral (wet stone, flint, slate). Yeast/lactic (bread, cream, butter).", ref:null },
    { id:122, category:"Service & Pairing", q:"What is the ideal serving temperature for a full-bodied white wine like white Burgundy?", a:"10–13°C (50–55°F). Slightly warmer than lighter whites so aromatic complexity can fully express. Too cold and the wine will taste closed and acidic; too warm and it will seem heavy and flabby.", ref:null },
    { id:123, category:"Labels & Law", q:"What does 'Cru' mean in French wine terminology?", a:"Cru means 'growth' and refers to a specific, classified vineyard or estate. Premier Cru (1st Growth or 1er Cru) and Grand Cru are the top two tiers in Burgundy. In Bordeaux, Cru Classé refers to châteaux classified in the 1855 Classification or equivalent. The term implies recognized quality of origin.", ref:null },
    { id:124, category:"Regions", q:"What is Chablis and why is it distinctive?", a:"Chablis is a cool-climate Chardonnay appellation in northern Burgundy, France. It is known for bone-dry, unoaked (or lightly oaked) whites with high acidity and a distinctive flinty/mineral character from Kimmeridgian limestone soils. Classifications: Petit Chablis, Chablis, Premier Cru, Grand Cru (7 vineyards).", ref:{ type:"map", label:"Chablis map", url:"https://www.wine-searcher.com/regions/chablis" } },
    { id:125, category:"Grapes & Varieties", q:"What is Gewurztraminer and what are its key characteristics?", a:"An aromatic white grape producing full-bodied, low-acid wines with explosive aromas: lychee, rose petal, Turkish delight, ginger, and spice. Often off-dry to sweet. The name means 'spiced Traminer.' Benchmark region: Alsace, France. Also grown in Germany, Alto Adige, and New Zealand.", ref:{ type:"search", label:"Gewurztraminer bottles", url:"https://www.wine-searcher.com/find/gewurztraminer" } },
    { id:126, category:"Vinification", q:"What is a 'varietal' wine vs. a 'blended' wine?", a:"A varietal wine is labeled by its dominant grape variety (e.g., Chardonnay, Merlot). A blended wine combines two or more varieties for balance and complexity (e.g., Bordeaux blend of Cabernet Sauvignon and Merlot, or GSM — Grenache, Syrah, Mourvèdre). Both approaches can produce world-class wines.", ref:null },
    { id:127, category:"Viticulture", q:"What is 'yield' in viticulture and how does it affect wine quality?", a:"Yield is the amount of fruit produced per hectare (measured in hectoliters per hectare, hl/ha). Lower yields generally concentrate flavors, sugars, and phenolic compounds in each grape. High yields dilute concentration. Appellation laws often set maximum yields to protect quality. Top estates further self-restrict their yields.", ref:null },
    { id:128, category:"Service & Pairing", q:"What is a Coravin and how does it work?", a:"A Coravin is a wine preservation tool that inserts a thin needle through the cork without removing it, extracts wine using argon gas pressure, and reseals the bottle. Since the cork is never fully pulled, the remaining wine is protected from oxidation and can be stored for months or years. Widely used in restaurants for by-the-glass programs of expensive wines.", ref:null },
    { id:129, category:"Regions", q:"What is Rioja Gran Reserva and what are its aging requirements?", a:"Rioja Gran Reserva is the top tier of Rioja classification, made only in exceptional vintages from the best vineyards. Red Gran Reserva requires minimum 5 years aging: at least 2 years in oak and 3 years in bottle. The result is a complex wine with tertiary aromas (leather, dried fruit, tobacco, cedar) and silky, integrated tannins.", ref:{ type:"search", label:"Rioja Gran Reserva bottles", url:"https://www.wine-searcher.com/find/rioja+gran+reserva" } },
    { id:130, category:"Grapes & Varieties", q:"What is Malbec and where is it most famous?", a:"Malbec is a thick-skinned red grape originally from southwest France (Cahors). It found its greatest expression in Argentina, particularly Mendoza. Argentine Malbec: deep purple color, plum, blackberry, violet, chocolate, and tobacco flavors with velvety tannins. It is Argentina's flagship variety and the country's most exported wine.", ref:{ type:"search", label:"Malbec Mendoza bottles", url:"https://www.wine-searcher.com/find/malbec+mendoza" } },
    { id:131, category:"Vinification", q:"What is 'lees aging' and what does it contribute to wine?", a:"Lees are the dead yeast cells and grape particles that settle after fermentation. Aging wine on its lees (sur lie) contributes: creaminess and texture (from autolysis releasing mannoproteins), bready/yeasty aromas, and protection from oxidation. Used in Muscadet (classic sur lie), white Burgundy, and Champagne (extended lees contact gives brioche character).", ref:null },
    { id:132, category:"Viticulture", q:"What is the difference between 'New World' and 'Old World' viticulture practices?", a:"Old World: traditional methods, lower yields enforced by law, minimal intervention, emphasis on terroir. New World: more technological innovation, irrigation common, higher yields acceptable, greater experimentation with winemaking techniques. However, the distinction is blurring — many New World producers now adopt Old World minimal-intervention approaches and vice versa.", ref:null },
    { id:133, category:"Labels & Law", q:"What does 'DOCG' mean and how does it differ from DOC in Italian wine?", a:"DOCG (Denominazione di Origine Controllata e Garantita) is Italy's highest wine classification. It includes all DOC requirements plus: a government tasting panel must approve each batch, yields are typically lower, and bottles carry a numbered neck seal (fascetta) guaranteeing authenticity. Examples: Barolo, Brunello di Montalcino, Chianti Classico, Amarone della Valpolicella.", ref:null },
    { id:134, category:"Regions", q:"What are the main wine regions of New Zealand and what are they known for?", a:"Marlborough (South Island): benchmark Sauvignon Blanc — intensely aromatic, passion fruit, gooseberry, high acidity. Central Otago: world's southernmost wine region, elegant Pinot Noir. Hawke's Bay: Bordeaux varieties and Syrah. Martinborough: Pinot Noir. Waipara/Canterbury: Riesling, Pinot Noir. New Zealand is a leading New World producer of aromatic whites and cool-climate reds.", ref:{ type:"map", label:"New Zealand wine map", url:"https://winefolly.com/learn/wine-region-maps/" } },
    { id:135, category:"Viticulture", q:"What is 'véraison' and why is it significant?", a:"Véraison is the onset of grape ripening, typically mid-summer. Red grapes change from green to purple or red; white grapes soften and turn golden-yellow. Sugar accumulation begins and acidity starts to decline. It marks the transition from the growth phase to the ripening phase — from this point, the countdown to harvest begins.", ref:null },
    { id:136, category:"Grapes & Varieties", q:"What is Moscato d'Asti and what makes it distinctive?", a:"Moscato d'Asti is a lightly sparkling (frizzante), low-alcohol (5–6.5% abv), sweet Italian wine made from the Moscato Bianco grape in Piedmont. It has intense aromas of peach, apricot, orange blossom, and honey. Made by stopping fermentation early to retain natural sweetness. Very different from dry Asti Spumante despite using the same grape.", ref:{ type:"search", label:"Moscato d'Asti bottles", url:"https://www.wine-searcher.com/find/moscato+asti" } },
    { id:137, category:"Tasting", q:"What is 'astringency' and what causes it in wine?", a:"Astringency is a drying, puckering, gripping sensation on the gums and inner cheeks caused by tannins binding to salivary proteins. It is distinct from bitterness (a taste) and is a textural perception. High tannin grapes (Nebbiolo, Cabernet Sauvignon, Sagrantino) produce highly astringent young wines that soften with aging as tannins polymerize.", ref:null },
    { id:138, category:"Labels & Law", q:"What does 'Spätburgunder' mean on a German wine label?", a:"Spätburgunder is the German name for Pinot Noir. Germany is actually one of the world's leading producers of Pinot Noir, with serious examples from Baden, Ahr (volcanic basalt soils), Pfalz, and Rheingau. German Spätburgunder tends toward elegance: medium ruby, red fruit, silky tannins, earthy complexity — more Burgundian than New World in style.", ref:{ type:"search", label:"Spätburgunder bottles", url:"https://www.wine-searcher.com/find/spatburgunder+germany" } },
  ],
  wset3: [
    { id:201, category:"Viticulture", q:"Explain the concept of terroir.", a:"The complete natural environment of a vineyard: climate (macroclimate, mesoclimate, microclimate), soil composition, topography, and aspect. Terroir expresses itself in the wine's character.", ref:null },
    { id:202, category:"Viticulture", q:"What is the difference between Continental, Maritime, and Mediterranean climates in viticulture?", a:"Continental: hot summers/cold winters, high diurnal range (Burgundy, Alsace). Maritime: moderated by ocean, mild but wet (Bordeaux). Mediterranean: hot dry summers, mild winters (Rhône, Spain).", ref:{ type:"map", label:"Climate zones map", url:"https://www.guildsomm.com/public_content/features/articles/b/blakeford/posts/wine-climate-zones" } },
    { id:203, category:"Regions", q:"Name the key Crus in the Médoc 1855 Classification.", a:"1st Growths (Premiers Crus): Lafite Rothschild, Latour, Margaux, Mouton Rothschild, Haut-Brion. These represent the apex of Bordeaux's Left Bank hierarchy.", ref:{ type:"search", label:"View 1855 classification bottles", url:"https://www.wine-searcher.com/find/1855+classified+growth+bordeaux" } },
    { id:204, category:"Grapes & Varieties", q:"Describe the key characteristics of Riesling from different climates.", a:"Cool (Mosel): high acidity, low alcohol, petrol/slate, delicate fruit. Medium (Alsace): richer, spicy, fuller body. Warm (Clare Valley, Aus): intense lime/citrus, high acidity, dry style.", ref:null },
    { id:205, category:"Vinification", q:"What is whole-bunch fermentation and why is it used?", a:"Grapes fermented with stems intact. Adds structure, spice, and complexity. Used in Pinot Noir (Burgundy) and Syrah (Northern Rhône). Requires very ripe stems to avoid green tannins.", ref:null },
    { id:206, category:"Vinification", q:"Explain Extended Maceration in red winemaking.", a:"Leaving wine on skins post-fermentation for days to weeks. Extracts more tannin, color, and phenolic compounds. Results in deeper color, more structured wines designed for long aging.", ref:null },
    { id:207, category:"Tasting", q:"How do you assess quality in WSET Level 3 conclusions?", a:"Faulty/Poor/Acceptable/Good/Very Good/Outstanding. Assess balance (between acidity, tannin, alcohol, fruit), length, intensity, complexity, and typicity to the variety/region.", ref:null },
    { id:208, category:"Labels & Law", q:"What does Grosses Gewächs (GG) mean in German wine?", a:"Grand Cru equivalent in the VDP classification. A dry wine from a top-classified single vineyard site. Must meet strict ripeness and yield requirements. Comparable to Premier/Grand Cru Burgundy.", ref:null },
    { id:209, category:"Regions", q:"What are the main sub-regions and styles of Champagne?", a:"Montagne de Reims (Pinot Noir), Vallée de la Marne (Pinot Meunier), Côte des Blancs (Chardonnay, Blanc de Blancs). Styles: Non-Vintage, Vintage, Prestige Cuvée, Rosé.", ref:{ type:"map", label:"Champagne region map", url:"https://www.champagne.fr/en/champagne-vineyard/champagne-viticultural-zones/map" } },
    { id:210, category:"Regions", q:"Explain the Burgundy classification hierarchy from broadest to most specific.", a:"Regional AOC (e.g., Bourgogne Rouge) → Village/Communal AOC (e.g., Gevrey-Chambertin) → Premier Cru (labeled 1er Cru + vineyard name) → Grand Cru (the vineyard name IS the AOC, e.g., Chambertin). Only 33 Grand Cru AOCs exist.", ref:{ type:"map", label:"Burgundy classification map", url:"https://www.burgundy-report.com/maps/" } },
    { id:211, category:"Viticulture", q:"What is diurnal temperature variation and why is it important?", a:"The difference between daytime high and nighttime low temperatures. Large diurnal range (e.g., Paso Robles, Mendoza, Mosel) preserves natural acidity and aromatic compounds while allowing full sugar ripeness — key for wines with both freshness and complexity.", ref:null },
    { id:212, category:"Vinification", q:"What is carbonic maceration and what style of wine does it produce?", a:"Fermentation occurring inside whole, intact berries before yeast can act. Produces low-tannin, intensely fruity, bubble-gum/banana-scented wines. Classic technique in Beaujolais Nouveau using Gamay.", ref:{ type:"search", label:"Beaujolais bottles", url:"https://www.wine-searcher.com/find/beaujolais" } },
    { id:213, category:"Grapes & Varieties", q:"Describe Grenache/Garnacha — its character and key regions.", a:"High alcohol, low tannin, low color, red/dark fruit (raspberry, kirsch), spice, and herbal notes. Prone to oxidation. Key regions: Châteauneuf-du-Pape, Priorat, Rioja (blending), Gigondas, Sardinia (Cannonau).", ref:{ type:"search", label:"Grenache bottles", url:"https://www.wine-searcher.com/find/grenache" } },
    { id:214, category:"Regions", q:"What makes the Mosel Valley unique for Riesling production?", a:"Slate (Schiefer) soils absorb and radiate heat, enabling ripening despite the cool climate. Steep south-facing slopes maximize sun exposure. The river moderates temperature. Results in wines of extraordinary finesse, low alcohol, and racy acidity.", ref:{ type:"map", label:"Mosel map", url:"https://www.wine-searcher.com/regions/mosel" } },
    { id:215, category:"Vinification", q:"What is the difference between a varietal and a blended wine?", a:"Varietal: made predominantly from a single grape variety (legal minimums vary: 75% in US/Australia, 85% in EU). Blend: intentional combination of varieties to achieve complexity, balance, and consistency (e.g., Bordeaux blends, GSM, Champagne).", ref:null },
    { id:216, category:"Labels & Law", q:"What are the key differences between DOC and DOCG in Italian wine law?", a:"DOC (Denominazione di Origine Controllata): controlled origin, regulated grapes and methods. DOCG (Garantita): the highest tier — adds government tasting panel approval, neck seal (fascetta), and stricter production rules. Examples: Barolo, Brunello, Chianti Classico.", ref:null },
    { id:217, category:"Tasting", q:"How does tannin evolve with bottle aging?", a:"Over time, tannin polymers bind together and precipitate as sediment, softening the wine's astringency. Young, grippy tannins become more velvety and integrated. This is why structured wines (Barolo, Bordeaux) improve significantly with age.", ref:null },
    { id:218, category:"Service & Pairing", q:"What is the principle behind pairing wine with acidic foods?", a:"The wine must have equal or greater acidity than the food, or it will taste flat and flabby. E.g., Muscadet with oysters (both high acid), Sancerre with chèvre (acid cuts through fat), Italian whites with tomato-based dishes.", ref:null },
    { id:219, category:"Regions", q:"Describe the key wine styles of the Rhône Valley (North vs. South).", a:"Northern Rhône: single-variety Syrah (Hermitage, Cornas, Crozes-Hermitage); whites from Marsanne/Roussanne/Viognier. Southern Rhône: GSM blends dominate (Châteauneuf-du-Pape, Gigondas); warmer, riper, more generous wines.", ref:{ type:"map", label:"Rhône Valley map", url:"https://www.wine-searcher.com/regions/rhone" } },
    { id:220, category:"Viticulture", q:"What are the key viticultural risks of a cool climate and how are they managed?", a:"Frost (spring bud break damage): managed by wind machines, heaters, water sprinklers, or site selection (slopes avoid cold air pooling). Fungal diseases (mildew, botrytis): managed by canopy management, copper/sulfur sprays, or organic/biodynamic methods. Underripeness: addressed by late harvesting, site selection (south-facing slopes), and low yields.", ref:null },
    { id:221, category:"Grapes & Varieties", q:"Describe the key sensory profile and aging potential of white Burgundy (Chardonnay).", a:"Village level: apple, citrus, light oak, medium body. Premier Cru: more complexity, stone fruit, mineral/chalk, greater structure. Grand Cru (Montrachet, Corton-Charlemagne): profound concentration, hazelnut, brioche, extraordinary aging potential (10–30+ years). All share hallmark Burgundian minerality and acidity.", ref:{ type:"search", label:"White Burgundy bottles", url:"https://www.wine-searcher.com/find/white+burgundy+chardonnay" } },
    { id:222, category:"Vinification", q:"What is the purpose and process of cold stabilization in white winemaking?", a:"Cold stabilization prevents tartrate crystals (cream of tartar) from forming in the bottle after release — which can alarm consumers who mistake them for glass. The wine is chilled to near freezing (–4°C) for 1–2 weeks so tartrates precipitate in tank and are filtered out. A cosmetic rather than quality-related process.", ref:null },
    { id:223, category:"Labels & Law", q:"What is the difference between 'Trocken' and 'Halbtrocken' on a German wine label?", a:"Trocken = dry (max 9 g/L residual sugar, or up to 18 g/L if acidity is within 2 g/L of RS). Halbtrocken = off-dry/half-dry (max 18 g/L RS). Feinherb is a similar informal term. These terms apply regardless of Prädikat level — even a Spätlese can be Trocken if fermented dry.", ref:null },
    { id:224, category:"Regions", q:"Describe the key features of Alsace wines and what makes the region distinctive.", a:"Located in northeastern France, sheltered by the Vosges Mountains (creating a dry, sunny microclimate). Produces mostly dry white wines from aromatic varieties: Riesling, Gewurztraminer, Pinot Gris, Muscat. Wines are single-varietal (unlike Champagne blends). Grand Cru system (51 sites). Germanic bottle shape but French winemaking approach.", ref:{ type:"map", label:"Alsace wine map", url:"https://www.wine-searcher.com/regions/alsace" } },
    { id:225, category:"Vinification", q:"Explain the process and purpose of fining in winemaking.", a:"Fining involves adding a substance (fining agent) to wine that binds to unwanted particles and causes them to precipitate out. Common agents: bentonite (removes proteins in whites — prevents heat haze), egg whites/albumin (softens tannins in reds), isinglass (clarifies whites gently), gelatin (reduces tannin and astringency). The wine is then racked or filtered. Vegan wines use bentonite or pea protein instead of animal-based agents.", ref:null },
    { id:226, category:"Regions", q:"Describe the key wine styles and producers of Napa Valley.", a:"Napa Valley (California) is world-famous for Cabernet Sauvignon: powerful, fruit-forward, opulent, high alcohol. Key sub-AVAs: Oakville (Harlan Estate, Opus One, Groth), Rutherford ('Rutherford dust' — cedar, earth), Stags Leap District (Clos du Val, Stag's Leap Wine Cellars — elegance). Also: Chardonnay and Sauvignon Blanc. Benchmark: Screaming Eagle, Dalla Valle, Dominus.", ref:{ type:"map", label:"Napa Valley map", url:"https://www.wine-searcher.com/regions/napa-valley" } },
    { id:227, category:"Grapes & Varieties", q:"Describe the key characteristics of Syrah/Shiraz across different climates.", a:"Northern Rhône (cool): dark ruby, violet/olive/smoked meat/black pepper, medium-full tannin, savory and mineral. Warm climate (Barossa): opaque purple, blackberry/plum/chocolate/licorice, fuller body, lower acidity, American oak influence. Both share: inky color, dark fruit, meat/spice character. Climate is the primary differentiator between styles.", ref:{ type:"search", label:"Syrah/Shiraz bottles", url:"https://www.wine-searcher.com/find/syrah+shiraz" } },
    { id:228, category:"Labels & Law", q:"What is the significance of 'Mise en bouteille au château/domaine' on a French label?", a:"Mise en bouteille au château (Bordeaux) or au domaine (Burgundy) means 'bottled at the estate.' This guarantees the wine was made and bottled by the producer who grew the grapes — not by a négociant. It is a mark of authenticity and estate control over the entire production process.", ref:null },
    { id:229, category:"Service & Pairing", q:"What wine styles pair best with spicy Asian cuisine?", a:"Off-dry or slightly sweet wines work best — residual sugar tames heat and spice. Best pairings: off-dry Riesling (Spätlese or Alsatian Demi-Sec), Gewurztraminer (spice mirrors spice), Viognier (floral aromatics complement), Pinot Gris. Avoid: high-tannin reds (tannin amplifies heat), high-alcohol wines (alcohol amplifies spice). Bubbles (sparkling) also cleanse the palate effectively.", ref:null },
    { id:230, category:"Regions", q:"Describe the key features and wine styles of Priorat, Spain.", a:"Priorat DOCa sits in the Tarragona mountains of Catalonia. Its defining feature is llicorella soil — ancient slate and quartz that forces vine roots deep. Old-vine Garnacha and Cariñena produce low-yielding, intensely concentrated wines: dark fruit, mineral, graphite, high alcohol (14–16%). Key producers: Álvaro Palacios (L'Ermita), Clos Mogador, Mas Doix. Priorat received DOCa status (like Rioja) in 2000.", ref:{ type:"map", label:"Priorat map", url:"https://www.wine-searcher.com/regions/priorat" } },
    { id:231, category:"Grapes & Varieties", q:"Describe Viognier's sensory profile and the challenge of winemaking with it.", a:"Viognier produces full-bodied, low-acid whites with intense aromas of peach, apricot, nectarine, honeysuckle, and violet. The challenge: it has a very narrow window between underripe (thin, bitter) and overripe (heavy, phenolic, loses aromatics). Picking timing is critical. Also prone to oxidation. Benchmark: Condrieu (Northern Rhône). Also grown in Languedoc and blended into Côte-Rôtie Syrah for aromatic lift.", ref:{ type:"search", label:"Viognier/Condrieu bottles", url:"https://www.wine-searcher.com/find/condrieu" } },
    { id:232, category:"Vinification", q:"What is the 'cap' in red winemaking and why must it be managed?", a:"During red wine fermentation, grape skins, seeds, and stems float to the top of the tank, forming a solid cap. Without management, the cap can trap heat (causing off-flavors), dry out (losing potential extraction), and become a breeding ground for bacteria. Management techniques: punch-down (pigeage), pump-over (remontage), rack-and-return (délestage), or rotary fermenters.", ref:null },
    { id:233, category:"Tasting", q:"How does oak influence the perception of tannin and acidity in red wine?", a:"New oak contributes additional tannins (ellagitannins) that can add drying/astringent texture when the wine is young. However, the microoxygenation from barrel pores helps polymerize tannins over time, softening them. Oak does not directly affect acidity but can make wine seem less acidic by adding sweetness (vanilla) and roundness. French oak: finer tannins, subtle spice. American oak: coarser tannins, more obvious coconut/vanilla.", ref:null },
    { id:234, category:"Labels & Law", q:"What is Crémant and how does it differ from Champagne?", a:"Crémant refers to traditional-method sparkling wine made outside the Champagne appellation. Examples: Crémant d'Alsace (Pinot Blanc, Auxerrois, Riesling), Crémant de Loire (Chenin Blanc, Cabernet Franc), Crémant de Bourgogne (Chardonnay, Pinot Noir), Crémant du Jura. All made by méthode traditionnelle with secondary fermentation in bottle. Typically less complex than Champagne due to shorter lees aging requirements, but excellent value.", ref:{ type:"search", label:"Crémant bottles", url:"https://www.wine-searcher.com/find/cremant" } },
    { id:235, category:"Vinification", q:"What is 'saignée' and when is it used in winemaking?", a:"Saignée (French: 'bleeding') is a technique where a portion of juice is bled off from a red wine fermentation tank shortly after crushing. This concentrates the remaining red must (higher skin-to-juice ratio) while the bled juice, with brief skin contact and pink color, is fermented separately as a rosé. A practical way to make both a concentrated red and a quality rosé simultaneously.", ref:null },
    { id:236, category:"Regions", q:"Describe the key wine styles and geography of Jerez (Sherry country).", a:"Jerez de la Frontera (Andalusia, southern Spain) sits on albariza soils — white limestone/chalk that retains moisture and reflects sunlight. The triangular 'Sherry Triangle' includes Jerez, El Puerto de Santa María, and Sanlúcar de Barrameda (home of Manzanilla). Hot, dry climate is moderated by Poniente (Atlantic) winds. Key varieties: Palomino Fino (all dry Sherry), Pedro Ximénez (sweet PX), Moscatel.", ref:{ type:"map", label:"Jerez/Sherry map", url:"https://www.wine-searcher.com/regions/jerez" } },
    { id:237, category:"Viticulture", q:"What is 'integrated pest management' (IPM) and how does it apply to viticulture?", a:"IPM is a sustainable approach that combines biological, cultural, and chemical methods to manage pests and diseases while minimizing environmental impact. In viticulture: monitoring pest populations before intervening, using beneficial insects (ladybirds, wasps) to control pests, selecting disease-resistant vine varieties, using pheromone disruption for moths, and applying chemicals only when thresholds are exceeded. A middle path between conventional and organic.", ref:null },
    { id:238, category:"Grapes & Varieties", q:"Describe the key characteristics of Gewurztraminer at WSET Level 3.", a:"Gewurztraminer produces deeply colored (pale gold to amber-gold), full-bodied, low-acid whites. Hallmark aromatics: lychee, rose petal, Turkish delight, ginger, cinnamon, and spice. The word 'Gewurz' means 'spiced.' Despite intense sweetness of aroma, most Alsatian versions are dry. Vendanges Tardives and SGN are lusciously sweet. Aging potential modest except for top SGN. Also grown in Germany, Alto Adige, and New Zealand.", ref:{ type:"search", label:"Gewurztraminer Alsace bottles", url:"https://www.wine-searcher.com/find/gewurztraminer+alsace" } },
    { id:239, category:"Tasting", q:"How does the WSET Level 3 SAT approach 'development' on the nose?", a:"Development describes how evolved the wine is: Youthful — primary fruit aromas dominate, wine shows its grape character, no tertiary development. Developing — some secondary (fermentation-derived) and early tertiary aromas beginning to emerge alongside primary fruit. Fully developed — tertiary aromas (leather, earth, dried fruit, mushroom, petrol) dominate; primary fruit has receded. Development correlates with age but also with winemaking style.", ref:null },
  ],
  wset4: [
    { id:301, category:"Vinification", q:"Describe the extended skin contact method for white wines (orange wine).", a:"White grapes fermented with skins for days to months. Extracts tannins, phenolics, and color (amber/orange). Results in oxidative, tannic white wines with textural weight. Historical practice revived in Georgia, Friuli, Slovenija.", ref:null },
    { id:302, category:"Viticulture", q:"Explain grapevine physiology: what is the role of photosynthesis in ripening?", a:"Leaves photosynthesize sunlight into sugars (glucose/fructose) transported to berries. Ripening requires adequate leaf area index. Canopy management controls balance between vegetative growth and fruit development.", ref:null },
    { id:303, category:"Regions", q:"Compare and contrast Piedmont's Barolo and Barbaresco.", a:"Both from Nebbiolo. Barolo: bigger production zone, 3+ years aging (5 for Riserva), more powerful/tannic, 3 main communes (La Morra, Barolo, Serralunga). Barbaresco: smaller, more elegant, 2+ years aging, communes include Barbaresco, Neive, Treiso.", ref:{ type:"map", label:"Piedmont DOCG map", url:"https://www.wine-searcher.com/regions/piedmont" } },
    { id:304, category:"Grapes & Varieties", q:"Describe the sensory profile and key regions for Nebbiolo.", a:"High acidity, very high tannin, medium-full body, low-medium color intensity. Aromas: tar, roses, red fruit, leather, tobacco, truffles. Key regions: Barolo, Barbaresco, Gattinara, Ghemme (Piedmont).", ref:{ type:"search", label:"Explore Nebbiolo bottles", url:"https://www.wine-searcher.com/find/nebbiolo" } },
    { id:305, category:"Service & Pairing", q:"What is the theory behind wine and food pairing at Diploma level?", a:"Match weight, intensity, and flavor components. Congruent pairing (similar flavors amplify). Complementary pairing (contrasting elements balance). Avoid tannic reds with fish (metallic). Acidic wines cut through fat. Sweet wines balance spice/sweetness.", ref:null },
    { id:306, category:"Labels & Law", q:"Explain the PDO (Protected Designation of Origin) system in EU wine law.", a:"EU's overarching framework replacing AOC/DOC/DO etc. PDO wines must originate exclusively from a defined geographic area. All aspects of production (varieties, yield, vinification) must comply with the product specification.", ref:null },
    { id:307, category:"Viticulture", q:"Explain the concept of canopy management and its effect on wine quality.", a:"Canopy management controls leaf and shoot density around the fruit zone. Goals: optimal sunlight penetration (ripeness, color, flavor), air circulation (disease prevention), and photosynthesis efficiency. Techniques: leaf removal, shoot thinning, trellising (VSP, Scott Henry, lyre). Over-shaded fruit produces green, underripe characters.", ref:null },
    { id:308, category:"Vinification", q:"What is sur lie aging and what does it contribute?", a:"Aging wine on its lees (dead yeast cells) post-fermentation. Autolysis of yeast cells releases mannoproteins and polysaccharides, adding creaminess, breadth of texture, yeast/bready notes, and protection from oxidation. Key in Muscadet, Champagne, white Burgundy.", ref:null },
    { id:309, category:"Vinification", q:"Describe the production of Amarone della Valpolicella.", a:"Grapes (Corvina, Rondinella, Molinara) are dried on bamboo racks (appassimento) for 90–120 days, concentrating sugars and flavors. Then fermented to near dryness. Results in a powerful (15–17% abv) wine with dried fruit, chocolate, and tobacco. Minimum 2 years aging (4 for Riserva).", ref:{ type:"search", label:"Amarone bottles", url:"https://www.wine-searcher.com/find/amarone+valpolicella" } },
    { id:310, category:"Regions", q:"Describe the key Crus of Burgundy's Côte de Beaune and their signature wines.", a:"Corton-Charlemagne (Grand Cru white — Chardonnay), Meursault (1er Cru whites — Perrières, Genevrières), Puligny-Montrachet and Chassagne-Montrachet (Grand Cru whites — Le Montrachet, Bâtard-Montrachet), Volnay and Pommard (elegant/structured Pinot Noir).", ref:{ type:"map", label:"Côte de Beaune map", url:"https://www.burgundy-report.com/maps/" } },
    { id:311, category:"Grapes & Varieties", q:"Compare Tempranillo's expression in Rioja vs. Ribera del Duero.", a:"Rioja: blended with Garnacha/Mazuelo/Graciano, aged in American oak (classic vanilla/dill), Crianza/Reserva/Gran Reserva tiers, more traditional. Ribera del Duero (Tinto Fino): higher altitude (850m+), more French oak, darker fruit, more structured/modern, less blending.", ref:{ type:"map", label:"Rioja vs Ribera map", url:"https://www.wine-searcher.com/regions/spain" } },
    { id:312, category:"Viticulture", q:"What are the main vine training systems and their viticultural rationale?", a:"VSP (Vertical Shoot Positioning): efficient, suited to cool climates, good canopy control. Gobelet/Bush vine: low yield, drought tolerant, no trellis (Rhône, Priorat). Pergola/Tendone: high canopy, shade (hot climates, Amarone). Scott Henry/Lyre: high vigor sites needing canopy division.", ref:null },
    { id:313, category:"Vinification", q:"Explain micro-oxygenation (MOX) and its purpose in winemaking.", a:"Controlled introduction of tiny amounts of oxygen to wine during elevage, mimicking barrel aging. Softens tannins, stabilizes color (polymerization of anthocyanins and tannins), and reduces harsh/reductive characters. Used in tanks as an alternative or supplement to barrel aging.", ref:null },
    { id:314, category:"Regions", q:"Describe the main wine styles and appellations of Tuscany.", a:"Chianti Classico DOCG (Sangiovese, Gallo Nero zone). Brunello di Montalcino DOCG (100% Sangiovese Grosso, 5 yrs aging). Vino Nobile di Montepulciano DOCG. Super Tuscans (IGT): Cabernet/Merlot/Syrah blends or Sangiovese blends (Sassicaia, Tignanello, Ornellaia).", ref:{ type:"map", label:"Tuscany map", url:"https://www.wine-searcher.com/regions/tuscany" } },
    { id:315, category:"Labels & Law", q:"What is the DOCG fascia (neck seal) and what does it guarantee?", a:"The fascetta is a government-issued numbered neck band on all DOCG wines. It guarantees authenticity, traceability, and that the wine passed a mandatory tasting panel evaluation. Each bottle is individually numbered and registered.", ref:null },
    { id:316, category:"Grapes & Varieties", q:"Describe the sensory profile of Chenin Blanc across styles.", a:"Chamomile/hay/quince/honey aromas. High acidity (hallmark regardless of sweetness). Sparkling: Crémant de Loire, Vouvray Brut. Dry: Savennières (mineral, austere). Off-dry/Demi-Sec: Vouvray, Montlouis. Sweet: Bonnezeaux, Quarts de Chaume (botrytis). Exceptional aging potential.", ref:{ type:"search", label:"Vouvray bottles", url:"https://www.wine-searcher.com/find/vouvray+chenin+blanc" } },
    { id:317, category:"Tasting", q:"How do primary, secondary, and tertiary aromas differ in WSET Level 4 analysis?", a:"Primary: grape-derived aromas (fresh fruit, floral, herbal, spice). Secondary: fermentation-derived (yeast/bread from autolysis, butter from MLF, sulfur). Tertiary: aging-derived — in oak (vanilla, cedar, smoke) or in bottle (petrol, leather, dried fruit, mushroom, earth). Tertiary aromas signal development.", ref:null },
    { id:318, category:"Vinification", q:"What is pigeage and how does it differ from remontage?", a:"Pigeage (punch-down): breaking the cap of skins by pushing it down into fermenting must. Gentler, better for Pinot Noir. Remontage (pump-over): pumping fermenting juice from the bottom over the cap. More extraction, better for Cabernet Sauvignon. Both integrate skins with juice for color/tannin extraction.", ref:null },
    { id:319, category:"Regions", q:"Describe the key fortified wines of Portugal and their production.", a:"Vintage Port: declared exceptional years, aged in bottle, dark/structured. LBV (Late Bottled Vintage): 4–6 years barrel aging. Tawny Port: extended oxidative barrel aging, amber/nutty (10, 20, 30, 40-year Tawny). White Port: dry to sweet. Madeira: volcanic island, estufagem heating, perpetually long-lived.", ref:{ type:"search", label:"Port wine bottles", url:"https://www.wine-searcher.com/find/vintage+port" } },
    { id:320, category:"Service & Pairing", q:"Explain the theory of pairing wine with umami-rich foods.", a:"Umami (glutamates in aged cheese, mushrooms, soy) amplifies bitterness and astringency in tannic wines and highlights acidity. Best pairings: umami + aged whites (aged Burgundy, Champagne), umami + low-tannin reds, or umami + oxidative wines (Sherry, Madeira) which share savory/nutty compounds.", ref:null },
    { id:321, category:"Viticulture", q:"What is biodynamic viticulture and how does it differ from organic?", a:"Organic: avoids synthetic pesticides/herbicides/fertilizers. Biodynamic (Demeter-certified): goes further — treats vineyard as a self-sustaining ecosystem; uses specific preparations (cow-manure horn/quartz), follows lunar/cosmic planting calendar, promotes biodiversity. Practitioners include DRC, Leroy, Zind-Humbrecht.", ref:null },
    { id:322, category:"Viticulture", q:"Explain the phenomenon of 'véraison' and its significance in vine physiology.", a:"Véraison is the onset of ripening, typically mid-summer. Red grapes turn from green to purple/red; white grapes soften and turn golden. Sugar accumulation begins; acidity starts to decrease. The transition from growth to ripening phase. Uneven véraison (caused by stress or disease) leads to heterogeneous ripeness — a challenge for harvest timing.", ref:null },
    { id:323, category:"Tasting", q:"What is the WSET Diploma approach to assessing a wine's aging potential?", a:"Consider: acidity (higher = longer potential), tannin level and quality (ripe vs. harsh), residual sugar (acts as preservative), alcohol level, concentration of fruit, and track record of the producer/vintage. Wines with high acidity, firm tannins, and concentration age longer. Balance at time of tasting is also key.", ref:null },
    { id:324, category:"Regions", q:"Describe the key styles and appellations of the Rhône Valley whites.", a:"Northern Rhône whites: Condrieu and Château-Grillet (100% Viognier — rich, floral, peach); Hermitage Blanc and Crozes-Hermitage Blanc (Marsanne/Roussanne — full, waxy, honeyed with age). Southern Rhône whites: Châteauneuf-du-Pape Blanc (Grenache Blanc, Clairette, Roussanne — rich, low acid, complex).", ref:{ type:"map", label:"Rhône whites map", url:"https://www.wine-searcher.com/regions/rhone" } },
    { id:325, category:"Vinification", q:"What is 'batonnage' and when is it employed?", a:"Batonnage is the stirring of lees (dead yeast cells) during barrel or tank aging. Done with a rod (baton) every few days to weeks. Purpose: adds texture, creaminess, and yeasty/bready complexity; prevents the lees from compacting and developing reductive (sulfurous) off-aromas. Classic for Burgundian Chardonnay and Muscadet.", ref:null },
    { id:326, category:"Labels & Law", q:"Explain the concept of 'Einzellage' and 'Grosslage' in German wine classification.", a:"Einzellage: individual vineyard site (e.g., Wehlener Sonnenuhr, Bernkasteler Doctor). The most specific and prestigious designation. Grosslage: a collective site name covering multiple Einzellagen in one general area — historically used to sell blended wines under a famous site name. VDP members now use Grosses Gewächs (GG) and Erste Lage to indicate quality clearly.", ref:null },
    { id:327, category:"Regions", q:"Describe the key wine regions and styles of Chile.", a:"Maipo Valley: Cabernet Sauvignon (Concha y Toro, Almaviva). Colchagua: Carménère (Chile's signature grape — bell pepper, dark fruit, green herb), Cabernet. Casablanca and San Antonio: cool, coastal; Sauvignon Blanc, Chardonnay, Pinot Noir. Elqui and Limarí: high-altitude, cool. Carménère was misidentified as Merlot until 1994 — now Chile's point of difference.", ref:{ type:"map", label:"Chile wine map", url:"https://www.wine-searcher.com/regions/chile" } },
    { id:328, category:"Viticulture", q:"What are the main causes of variation between vintages and how do they affect wine style?", a:"Spring frost (can devastate yields and delay ripening), summer heat spikes (accelerate ripening, risk sunburn, low acidity), drought (stress can concentrate or shrink grapes), rainfall at harvest (dilutes wine, promotes rot). Great vintages combine: warm, dry growing seasons with preserved acidity and cool nights. Poor vintages: uneven ripeness, rot, dilution from rain.", ref:null },
    { id:329, category:"Tasting", q:"How do you assess and describe 'minerality' in wine at Diploma level?", a:"Minerality is a contested term describing sensations of wet stone, flint, chalk, or saline rather than a distinct aroma. Possible origins: vineyard soil geology (Kimmeridgian limestone in Chablis), reductive winemaking (preserves sulfur compounds), low-pH acidity perception, or terroir-derived compounds. At Diploma level: describe the sensation precisely (saline, stony, flinty, chalky) rather than just using 'mineral' as a catch-all.", ref:null },
    { id:330, category:"Vinification", q:"What is the difference between natural wine, organic wine, and biodynamic wine?", a:"Organic: no synthetic pesticides, herbicides, or fertilizers in the vineyard; certified (EU Organic, USDA Organic). Biodynamic: organic + holistic ecosystem management + Demeter preparations + lunar calendar; stricter than organic. Natural wine: no legal definition — typically organic/biodynamic farming, wild yeast fermentation, minimal SO2, no fining or filtration; can be controversial for consistency. All three are winemaking philosophies, not quality guarantees.", ref:null },
    { id:331, category:"Labels & Law", q:"What is 'En Primeur' and how does it work as a wine purchasing system?", a:"En Primeur (futures) is a system, pioneered in Bordeaux, where wine is sold before it is bottled. Buyers purchase wine in spring after harvest at lower prices, receiving delivery 18–24 months later. Advantages: access to allocated wines, lower price. Risks: price may fall, producer may disappoint, long wait. Top Bordeaux châteaux, Burgundy, and Rhône all offer En Primeur allocations through négociants.", ref:null },
    { id:332, category:"Regions", q:"Describe the key wine regions and styles of the Douro Valley, Portugal.", a:"The Douro Valley is Portugal's most important fine wine region, terraced into steep schist hillsides along the Douro River. Historically famous for Port (fortified wine: Touriga Nacional, Touriga Franca, Tinta Roriz/Aragonez). Increasingly renowned for unfortified Douro reds and whites: concentrated, mineral, with indigenous varieties. Sub-regions: Baixo Corgo (wetter, lighter), Cima Corgo (classic Port heartland), Douro Superior (driest, most remote). Top producers: Quinta do Crasto, Niepoort, Ramos Pinto.", ref:{ type:"map", label:"Douro Valley map", url:"https://www.wine-searcher.com/regions/douro" } },
    { id:333, category:"Viticulture", q:"What are 'phenolic maturity' and 'physiological ripeness' and why do they matter at Diploma level?", a:"Sugar ripeness (measured in Brix/°Oechsle) occurs before physiological ripeness — the point when skins, seeds, and stems have fully developed ripe tannins and flavors. Harvesting at sugar ripeness but before physiological ripeness yields wines with harsh, green tannins. Waiting for physiological ripeness risks overripe fruit and high alcohol. The challenge: synchronizing both forms of ripeness, especially in warm climates where sugar rushes ahead of phenolic development.", ref:null },
    { id:334, category:"Grapes & Varieties", q:"Describe the key differences between Pinot Noir from Burgundy, Oregon, and New Zealand in a comparative tasting.", a:"Burgundy: translucent ruby, earthy/forest floor/iron, red cherry, silky tannins, medium acidity, mineral finish, restrained. Oregon (Willamette): slightly deeper, more red and black fruit, earthier than NZ but less than Burgundy, good acidity, forest floor. NZ (Central Otago): deeper ruby, more intense dark cherry/plum, less earthy, rounder tannins, higher alcohol, fruit-forward. Climate and soil drive the differences; Burgundy is the benchmark for complexity and terroir expression.", ref:{ type:"search", label:"Pinot Noir regional comparison", url:"https://www.wine-searcher.com/find/pinot+noir" } },
    { id:335, category:"Service & Pairing", q:"Explain the concept of 'regional pairing' and give three examples.", a:"Regional pairing means matching wines with foods from the same geographic area — the philosophy that local food and wine evolved together and are naturally complementary. Examples: Muscadet with Breton oysters (Loire/Atlantic coast); Barolo with white truffle and Piedmontese beef (Piedmont); Alsatian Riesling with choucroute garnie (Alsace). The shared terroir creates natural flavor bridges between local wine and cuisine.", ref:null },
    { id:336, category:"Tasting", q:"What is 'reductive winemaking' and how do you identify its hallmarks in a blind tasting?", a:"Reductive winemaking minimizes oxygen contact at all stages — early harvest, cold fermentation, inert gas blanketing, minimal racking, unfined/unfiltered. Goal: preserve freshness, aromatics, and delicate fruit. Hallmarks in the glass: pale color, intense primary/secondary aromas, struck match or sulfurous note (reduction — dissipates with aeration), crisp acidity, no oak influence. Common in Loire whites (Muscadet, Sancerre), Chablis, some natural wines, and modern-style Mosel Riesling.", ref:null },
    { id:337, category:"Regions", q:"Describe the key wine regions and styles of Germany's VDP estates.", a:"The VDP (Verband Deutscher Prädikatsweingüter) is Germany's top producers' association. Their four-tier classification: Gutswein (estate wine) → Ortswein (village wine) → Erste Lage (Premier Cru equivalent, marked 1ste) → Grosses Gewächs/GG (Grand Cru equivalent — dry wines only from top single sites). GG Rieslings from Mosel (Bernkasteler Doctor, Wehlener Sonnenuhr), Rheingau (Rüdesheimer Berg Schlossberg), and Pfalz are world-class. GG must pass blind tasting approval.", ref:{ type:"map", label:"Germany VDP regions", url:"https://www.wine-searcher.com/regions/germany" } },
    { id:338, category:"Vinification", q:"Explain the production of Vin de Paille and what distinguishes it from other dessert wines.", a:"Vin de Paille (straw wine) is made by drying harvested grapes on straw mats or hanging them for 6–12 weeks to concentrate sugars through desiccation (not botrytis). Produced in Jura (Savagnin, Chardonnay, Poulsard), Hermitage (Roussanne, Marsanne), and Alsace. The drying concentrates sugars to extraordinary levels. Wines are rich, complex, and age magnificently — dried fruit, honey, spice, caramel. Very low yields (one bottle per vine) make them rare and expensive.", ref:{ type:"search", label:"Vin de Paille bottles", url:"https://www.wine-searcher.com/find/vin+de+paille" } },
    { id:339, category:"Grapes & Varieties", q:"Describe the key sensory profiles of Marsanne and Roussanne and their blending role.", a:"Marsanne: full-bodied, low acidity, waxy/almond/marzipan/white flowers when young; develops extraordinary complexity with age (golden, honeyed, beeswax, quince, nuts). Roussanne: more aromatic, higher acidity, herbal/floral/pear, adds freshness and finesse to Marsanne's weight. Blended together in Northern Rhône whites (Hermitage Blanc, Crozes-Hermitage) and Châteauneuf-du-Pape Blanc. Both can be monumental white wines that age 20+ years.", ref:{ type:"search", label:"Hermitage Blanc bottles", url:"https://www.wine-searcher.com/find/hermitage+blanc" } },
    { id:340, category:"Viticulture", q:"What is 'lyre training' and what viticultural problems does it solve?", a:"Lyre (or U-trellis) training divides the vine's canopy into two vertical walls angled outward in a U or lyre shape. Benefits: dramatically increases leaf surface area for photosynthesis, improves light penetration and air circulation into both canopy walls, reduces disease pressure, suitable for high-vigor sites where a single vertical canopy would become too dense. Used in Bordeaux, Burgundy, and California for problematic high-vigor clones or rootstocks.", ref:null },
    { id:341, category:"Labels & Law", q:"Explain the Burgundy appellation system's treatment of 'monopoles'.", a:"A monopole is a vineyard or appellation controlled entirely by a single producer — they own 100% of the vines. The most famous monopole in Burgundy is Romanée-Conti (Domaine de la Romanée-Conti, 1.8 ha Grand Cru). Others: La Tâche (DRC), Clos des Mouches (Drouhin — 1er Cru), Clos Saint-Jacques (majority owned by Rousseau). Monopoles guarantee that all wine under that label comes from one producer's stewardship of the vineyard — important for quality consistency.", ref:null },
    { id:342, category:"Viticulture", q:"Explain the difference between 'macroclimate', 'mesoclimate', and 'microclimate' in viticulture.", a:"Macroclimate (regional climate): the broad climatic conditions of a wine region — e.g., Burgundy's continental climate. Mesoclimate (site climate): the specific climate of a vineyard or hillside — e.g., a south-facing slope in the Côte d'Or is warmer than a valley floor. Microclimate (vine-level climate): the immediate environment around individual vines — influenced by canopy density, row orientation, soil reflectivity, and proximity to water bodies. Winemakers can manage microclimate through canopy management; mesoclimate is the key terroir differentiator between vineyards.", ref:null },
    { id:343, category:"Regions", q:"Describe the main wine styles and classifications of Alsace in detail.", a:"Alsace produces mostly dry varietal whites protected from Atlantic rain by the Vosges Mountains. The 51 Grand Cru vineyards must use only Riesling, Gewurztraminer, Pinot Gris, or Muscat. Special designations: Vendanges Tardives (VT — late harvest, botrytis or overripe; minimum 224–270 g/L must weight depending on variety) and Sélection de Grains Nobles (SGN — noble rot only, 270–306 g/L — rare, lusciously sweet). Crémant d'Alsace is the appellation's sparkling wine (traditional method). Top producers: Zind-Humbrecht, Trimbach (Clos Sainte Hune Riesling), Weinbach, Hugel.", ref:{ type:"map", label:"Alsace map", url:"https://www.wine-searcher.com/regions/alsace" } },
    { id:344, category:"Vinification", q:"What is 'élevage' and what decisions does a winemaker make during this phase?", a:"Élevage (French: 'raising' or 'upbringing') is the period between fermentation and bottling — typically several months to years. Key decisions: vessel type (new vs. old oak, large vs. small format, concrete, amphorae, stainless steel); duration of aging; whether to rack (move wine off lees) and how often; use of batonnage (lees stirring); SO2 additions; timing and method of fining and filtration; and blending. These choices shape the wine's texture, flavor complexity, and stability far more than most consumers realize.", ref:null },
    { id:345, category:"Grapes & Varieties", q:"Describe the key wine styles made from Sémillon and its blending role.", a:"Sémillon is a full-bodied, low-acid white grape. Dry/unblended: Hunter Valley (Australia) — extraordinary ageability, starts thin and lemon-grassy, develops into toasty/honeyed/lanolin complexity over 10–20 years with no oak. Bordeaux Blanc: blended with Sauvignon Blanc (Graves, Pessac-Léognan) — Sauvignon adds aromatics/acidity, Sémillon adds body/texture. Sauternes: Sémillon's thin skin makes it highly susceptible to Botrytis cinerea (noble rot) — produces the world's greatest sweet white wine alongside Sauvignon Blanc and Muscadelle.", ref:{ type:"search", label:"Hunter Valley Semillon bottles", url:"https://www.wine-searcher.com/find/hunter+valley+semillon" } },
    { id:346, category:"Tasting", q:"How does WSET Diploma assess the 'balance' of a wine and what does it mean for ageability?", a:"Balance at Diploma level considers the harmony between all structural components: acidity (freshness, spine), tannin (grip, structure), alcohol (body, warmth), sweetness (counterpoint to acid/tannin), and fruit concentration. A balanced wine has no single element dominating. For ageability: high acidity + firm tannins + concentration signals long potential; low acidity or harsh tannins signals short cellaring. Wines in balance when young tend to improve; those already showing imbalance (too alcoholic, too tannic) generally do not improve with age.", ref:null },
    { id:347, category:"Regions", q:"Describe the key wine styles and geography of Ribera del Duero.", a:"Ribera del Duero DO sits on a high plateau (850–1,000m elevation) along the Duero River in Castilla y León, Spain. Continental climate with extreme diurnal range — hot days and very cold nights preserve acidity in the ripe Tinto Fino (Tempranillo). Soils: limestone and sandy alluvium. Wines are typically 100% Tempranillo (unlike Rioja blends), aged predominantly in French oak, with dark fruit, graphite, leather, and firm structure. Flagship estates: Vega Sicilia (Único — Spain's most prestigious wine), Pingus, Pesquera, Emilio Moro, Protos.", ref:{ type:"map", label:"Ribera del Duero map", url:"https://www.wine-searcher.com/regions/ribera-del-duero" } },
    { id:348, category:"Labels & Law", q:"Explain the concept of 'Geographical Indication' (GI) within Australian wine law.", a:"Australia's GI system defines geographic zones, regions, and sub-regions. Unlike European AOC/DOC, Australian GIs impose no restrictions on grape varieties, yields, or winemaking methods — they only guarantee geographic origin. The Geographical Indications Committee approves new GIs based on petitions. Key GIs: Barossa Valley, Eden Valley, Coonawarra (famous terra rossa soils), Margaret River, Yarra Valley, Clare Valley. Label rules: if a GI, variety, or vintage is stated, 85% of the wine must come from that source.", ref:null },
    { id:349, category:"Vinification", q:"What is 'tartrate stabilization' and what are the different methods used?", a:"Tartrate crystals (potassium bitartrate/cream of tartar) can form in bottled wine when it is chilled, alarming consumers who may mistake them for glass. Methods to prevent this: Cold stabilization — chilling wine to –4°C for 1–2 weeks so crystals precipitate before bottling (most common). Electrodialysis — selectively removes potassium and tartrate ions without cold treatment (less energy-intensive). Metatartaric acid addition — temporarily inhibits crystallization but breaks down after 1–2 years (only for early-drinking wines). Mannoproteins from lees naturally inhibit tartrate crystallization.", ref:null },
    { id:350, category:"Grapes & Varieties", q:"Describe the key characteristics and regions of Grenache Blanc and Vermentino.", a:"Grenache Blanc: full-bodied, low acidity, herbal/anise/white fruit aromas, prone to oxidation. Key in Southern Rhône whites (Châteauneuf-du-Pape Blanc), Roussillon, and Spanish whites. Must be harvested early to preserve freshness. Vermentino (Rolle in Provence): aromatic, medium-high acidity, bitter almond finish, citrus/white peach/herbal notes. Key in Sardinia (Vermentino di Gallura DOCG — most complex), Corsica (Rolle), Languedoc-Roussillon, and Liguria. Both are warm-climate whites gaining increasing quality recognition.", ref:{ type:"search", label:"Vermentino di Gallura bottles", url:"https://www.wine-searcher.com/find/vermentino+sardinia" } },
    { id:351, category:"Service & Pairing", q:"Explain the Diploma-level theory of 'congruent' vs. 'contrasting' food and wine pairings with examples.", a:"Congruent pairing: wine and food share similar flavor compounds, amplifying each other. Example: aged Champagne (yeasty, nutty) with aged Comté cheese (nutty, crystalline) — shared nutty/umami compounds intensify on the palate. Contrasting pairing: opposing elements create balance. Example: sweet Sauternes with salty Roquefort — sweetness neutralizes saltiness; acidity cuts through blue cheese fat. Both approaches work; neither is superior. The key is that the pairing creates a third flavor experience greater than either component alone.", ref:null },
  ],
  cs1: [
    { id:401, category:"Service & Pairing", q:"What are the 5 basic steps of tableside wine service?", a:"1) Present the bottle (label facing guest). 2) Cut foil below second lip. 3) Insert and extract cork cleanly. 4) Wipe the lip. 5) Pour a taste for the host, then serve guests, host last.", ref:null },
    { id:402, category:"Grapes & Varieties", q:"Name the 6 noble grape varieties.", a:"Cabernet Sauvignon, Merlot, Pinot Noir, Chardonnay, Sauvignon Blanc, Riesling. (Some lists also include Syrah/Shiraz.)", ref:null },
    { id:403, category:"Service & Pairing", q:"What temperature should Champagne be served at?", a:"6–8°C (42–46°F). Properly chilled to preserve bubbles and freshness.", ref:null },
    { id:404, category:"Tasting", q:"What are the four phases of the Court of Master Sommeliers blind tasting grid?", a:"Sight (color, clarity, intensity, viscosity) → Smell (fruit aromas, earth/mineral, oak, development) → Taste (all structural components + finish) → Conclusions (grape, country, region, vintage).", ref:null },
    { id:405, category:"Service & Pairing", q:"What is the proper sequence for serving wines at a dinner?", a:"Sparkling → White → Red → Sweet/Dessert. Within each category: lighter before fuller-bodied, younger before older, drier before sweeter. This progression preserves palate sensitivity.", ref:null },
    { id:406, category:"Grapes & Varieties", q:"What are the primary flavor descriptors for Cabernet Sauvignon?", a:"Black currant (cassis), black cherry, cedar, tobacco, graphite, green bell pepper (when underripe). With oak: vanilla, toast, cigar box. With age: leather, earth, secondary fruit. Hallmark: firm, structured tannins and full body.", ref:{ type:"search", label:"Cabernet Sauvignon bottles", url:"https://www.wine-searcher.com/find/cabernet+sauvignon" } },
    { id:407, category:"Regions", q:"Name the major wine-producing states in the United States.", a:"California (Napa, Sonoma, Central Coast), Oregon (Willamette Valley — Pinot Noir), Washington State (Columbia Valley — Cabernet, Riesling), New York (Finger Lakes — Riesling, Pinot Noir), Virginia, and Texas.", ref:{ type:"map", label:"US wine regions", url:"https://winefolly.com/learn/wine-region-maps/" } },
    { id:408, category:"Labels & Law", q:"What does AVA stand for and what does it mean?", a:"American Viticultural Area — a federally designated grape-growing region in the US with specific geographic boundaries. Unlike European appellations, AVAs do NOT regulate grape varieties, yields, or winemaking methods. A label showing an AVA requires 85% of grapes from that area.", ref:null },
    { id:409, category:"Service & Pairing", q:"When should a sommelier recommend decanting a wine?", a:"Young tannic reds (to open up/aerate — 1–2 hours). Old wines with sediment (careful slow pour, stop at sediment). Never decant: delicate aged wines needing short exposure, most whites, Champagne/sparkling wines.", ref:null },
    { id:410, category:"Tasting", q:"How do you evaluate color in a white wine and what does it indicate?", a:"Pale lemon: young, cool climate, unoaked (Pinot Grigio, Muscadet). Medium gold: some age or oak (Chardonnay). Deep gold/amber: late harvest sweetness, oxidative aging, or extended skin contact. Browning at rim = oxidation or significant age.", ref:null },
    { id:411, category:"Vinification", q:"What is the role of sulfur dioxide (SO2) in winemaking?", a:"SO2 is an antioxidant and antimicrobial agent. It protects wine from oxidation and prevents growth of unwanted bacteria and wild yeasts. Added at crush, during aging, and at bottling. Contains Sulfites labeling required in US for wines over 10ppm.", ref:null },
    { id:412, category:"Grapes & Varieties", q:"Describe the key flavor profile of Pinot Noir.", a:"Light to medium ruby color, low-medium tannin, high acidity. Red fruit (cherry, raspberry, strawberry), earthy/forest floor, mushroom, spice. With age: leather, game, beet. Key regions: Burgundy, Willamette Valley, Sonoma Coast, Central Otago.", ref:{ type:"search", label:"Pinot Noir bottles", url:"https://www.wine-searcher.com/find/pinot+noir" } },
    { id:413, category:"Service & Pairing", q:"What are the key etiquette points for opening and serving sparkling wine?", a:"Chill well (6–8°C). Remove foil and cage carefully keeping thumb on cork. Grip cork firmly, rotate BOTTLE not cork. Ease cork out gently — whisper, not pop. Angle bottle 45°. Pour slowly in two stages to control foam. Never shake.", ref:null },
    { id:414, category:"Regions", q:"What makes Napa Valley famous and what are its key sub-AVAs?", a:"Napa Valley (California) is world-renowned for Cabernet Sauvignon. Key sub-AVAs: Oakville (Harlan, Opus One), Rutherford (Rubicon), Stags Leap District, Howell Mountain (elevation), Carneros (cooler, Chardonnay/Pinot Noir).", ref:{ type:"map", label:"Napa Valley map", url:"https://www.wine-searcher.com/regions/napa-valley" } },
    { id:415, category:"Tasting", q:"What is balance in a wine and why does it matter?", a:"Balance occurs when no single element (acidity, tannin, alcohol, sweetness, fruit) dominates the others — they integrate harmoniously. A balanced wine feels complete and seamless. Imbalance shows as too much alcohol (hot), too much acid (harsh), over-oaked, or too sweet.", ref:null },
    { id:416, category:"Vinification", q:"What is the difference between new and old oak barrels?", a:"New oak: significant flavor/tannin contribution (vanilla, toast, spice). Old oak (1+ years): mainly provides gentle oxygenation with minimal flavor impact. Small barrels (225L Barrique) give more surface-area-to-wine contact than large format (500L Demi-muid, foudre).", ref:null },
    { id:417, category:"Labels & Law", q:"What does Estate Bottled mean on a US wine label?", a:"The winery grew all the grapes at their estate vineyards within the same AVA where the winery is located, and made and bottled the wine. A stricter designation than just bottled by. Indicates vertical integration and full producer control.", ref:null },
    { id:418, category:"Service & Pairing", q:"What is the classic pairing for Champagne?", a:"Champagne's high acidity, effervescence, and yeasty richness pairs classically with: oysters and raw shellfish, fried foods (salt + acid cleanse), aged/salty cheeses (Gruyère, Comté), caviar, and light canapés. Rich Blanc de Blancs pairs with lobster.", ref:null },
    { id:419, category:"Regions", q:"What are the main wine-producing countries of South America?", a:"Argentina (Mendoza — Malbec; Patagonia — cool-climate whites), Chile (Maipo, Colchagua, Casablanca — Cabernet, Carménère, Sauvignon Blanc), Uruguay (Tannat), Brazil (Serra Gaúcha), Bolivia (high-altitude viticulture).", ref:{ type:"map", label:"South America wine map", url:"https://winefolly.com/learn/wine-region-maps/" } },
    { id:420, category:"Tasting", q:"What is the difference between 'aroma' and 'bouquet' in wine terminology?", a:"Aroma refers to scents that come directly from the grape variety (primary: fruit, floral, herbal). Bouquet refers to scents that develop through fermentation (secondary: yeast, bread) and aging (tertiary: leather, earth, tobacco, dried fruit). In casual use, the terms are interchangeable, but technically bouquet implies developed, aged complexity.", ref:null },
    { id:421, category:"Regions", q:"What are the key wine regions and varieties of Washington State?", a:"Columbia Valley AVA is the main umbrella. Key sub-AVAs: Walla Walla (Cabernet Sauvignon, Merlot, Syrah — Leonetti, L'Ecole), Horse Heaven Hills (Cabernet Sauvignon, Riesling), Yakima Valley (Riesling, Syrah, Chardonnay). Washington Riesling is world-class. The region has extreme diurnal range (hot days, very cold nights).", ref:{ type:"map", label:"Washington State wine map", url:"https://www.wine-searcher.com/regions/washington" } },
    { id:422, category:"Vinification", q:"What is 'cold soaking' (pre-fermentation maceration) and why is it used?", a:"Cold soaking involves holding crushed red grapes at low temperature (5–10°C) for 3–5 days before fermentation begins. Without alcohol present, only color pigments and soft aromatic compounds are extracted — not harsh tannins. Results in more fruit-forward, deeply colored wines with softer structure. Common for Pinot Noir.", ref:null },
    { id:423, category:"Service & Pairing", q:"What is the correct order for tasting wines in a sommelier exam flight?", a:"Always taste lightest to heaviest: sparkling first, then whites (lightest to richest), then rosé, then reds (lightest to fullest), then sweet/fortified last. This order prevents heavier wines from overwhelming the palate and masking lighter wine characteristics.", ref:null },
    { id:424, category:"Labels & Law", q:"What does 'Vieilles Vignes' mean on a wine label?", a:"Vieilles Vignes is French for old vines. There is no legal minimum age definition — it is unregulated. Generally implies vines over 30–40 years old. Older vines produce lower yields with naturally concentrated fruit. The term is used as a quality signal by producers across France and internationally.", ref:null },
    { id:425, category:"Grapes & Varieties", q:"What are the characteristics of Zinfandel and where is it grown?", a:"Zinfandel (Primitivo in Italy) is grown primarily in California. It produces bold, high-alcohol (14–16%) reds with blackberry, raspberry jam, black pepper, and spice. Ranges from light rosé (White Zinfandel) to powerful, tannic reds. Old-vine Zinfandel from Dry Creek Valley, Lodi, and Paso Robles produces concentrated, complex wines.", ref:{ type:"search", label:"Zinfandel bottles", url:"https://www.wine-searcher.com/find/zinfandel+california" } },
    { id:426, category:"Service & Pairing", q:"What is the difference between a 'Burgundy' and a 'Bordeaux' style wine glass?", a:"Burgundy glass: wider bowl, shorter chimney — designed to funnel delicate Pinot Noir aromas to the nose; also used for aromatic whites. Bordeaux glass: taller, narrower bowl — directs wine to the back of the mouth to soften Cabernet Sauvignon tannins; also suits full-bodied reds. Both are larger than everyday glasses to allow proper swirling.", ref:null },
    { id:427, category:"Tasting", q:"What is 'typicity' and why is it important in wine evaluation?", a:"Typicity refers to how closely a wine expresses the expected characteristics of its grape variety, region, or appellation. A highly typical Chablis should be dry, high-acid, mineral, unoaked. Typicity is assessed in both WSET and CMS tasting — it answers whether a wine 'tastes like it's supposed to.' High typicity + high quality = the benchmark expression of its type.", ref:null },
    { id:428, category:"Regions", q:"What are the key wine regions of Oregon and what grapes do they specialize in?", a:"Willamette Valley: world-class Pinot Noir (Dundee Hills, Eola-Amity Hills, Ribbon Ridge) and Chardonnay. Umpqua Valley: warmer, Pinot Noir and Bordeaux varieties. Rogue Valley: warmest, Bordeaux and Rhône varieties. Applegate Valley: Cabernet Sauvignon. Oregon is defined by cool-climate, Burgundian-style wines — lighter, more acidic, and earthier than California equivalents.", ref:{ type:"map", label:"Oregon wine map", url:"https://www.wine-searcher.com/regions/oregon" } },
    { id:429, category:"Labels & Law", q:"What does 'Reserve' mean on a US wine label?", a:"In the United States, 'Reserve' has no legal definition and is unregulated — any producer can use it on any wine regardless of aging, selection, or quality. In contrast, European terms like Reserva (Spain) and Riserva (Italy) have strict legal aging requirements. American consumers should look for producer reputation rather than relying on Reserve as a quality indicator.", ref:null },
    { id:430, category:"Tasting", q:"What are 'secondary aromas' in wine and give three examples?", a:"Secondary aromas develop during fermentation from yeast activity. Examples: bread dough or brioche (from yeast autolysis), butter or cream (from malolactic fermentation converting malic to lactic acid), and yeast/lager-like notes. These are distinct from primary (grape-derived) aromas and tertiary (aging-derived) aromas. Common in Champagne, oaked Chardonnay, and barrel-fermented whites.", ref:null },
    { id:431, category:"Service & Pairing", q:"How do you properly store wine in a restaurant cellar?", a:"Constant temperature (12–14°C/54–57°F) — avoid fluctuations. High humidity (70–80%) — prevents corks from drying. Darkness — UV light damages wine. Vibration-free — movement disturbs sediment and can accelerate aging negatively. Bottles stored on their sides (cork wines) to keep corks moist. White and sparkling wines in coolest zone; reds in slightly warmer section. Fortified wines can stand upright.", ref:null },
    { id:432, category:"Regions", q:"What makes the Willamette Valley ideal for Pinot Noir?", a:"The Willamette Valley in Oregon has a cool, maritime-influenced climate moderated by the Coast Range. The growing season is long, preserving acidity while allowing flavor development. Soils vary: volcanic Jory soils (Dundee Hills) give structured, earthy Pinot; Willakenzie sedimentary soils (Ribbon Ridge) yield silky, elegant styles. The valley sits at similar latitude to Burgundy (~45°N).", ref:{ type:"map", label:"Willamette Valley map", url:"https://www.wine-searcher.com/regions/willamette-valley" } },
    { id:433, category:"Grapes & Varieties", q:"What is Sauvignon Blanc and what are its hallmark characteristics?", a:"Sauvignon Blanc is a green-skinned grape producing dry, crisp whites with high acidity. Hallmark aromas: gooseberry, passion fruit, citrus (cool climate); tropical fruit (warm climate); grass, green pepper, and 'cat's pee' (from thiols). Key regions: Loire Valley (Sancerre, Pouilly-Fumé), Marlborough NZ (benchmark), Bordeaux (blended with Sémillon in Graves).", ref:{ type:"search", label:"Sauvignon Blanc bottles", url:"https://www.wine-searcher.com/find/sauvignon+blanc" } },
    { id:434, category:"Labels & Law", q:"What is a 'négociant' in the wine trade?", a:"A négociant (merchant) is a wine producer who buys grapes, grape juice, or finished wine from growers and then blends, ages, and sells the wine under their own label. Common in Burgundy (Louis Jadot, Louis Latour, Joseph Drouhin) and Champagne (most major houses). Négociants allow production at scale; top négociants can match estate-bottled wines in quality. Contrasts with domaine (estate) bottling.", ref:null },
    { id:435, category:"Tasting", q:"What does 'retronasal olfaction' mean and why does it matter in wine tasting?", a:"Retronasal olfaction is the perception of aromas when wine is in the mouth — volatile aromatic compounds travel up through the back of the throat to the olfactory receptors in the nasal cavity. This is distinct from orthonasal smelling (sniffing the glass directly). Most of what we call 'flavor' is actually retronasal smell. This is why chewing food or swirling wine in the mouth intensifies flavor perception.", ref:null },
    { id:436, category:"Regions", q:"What are the key Champagne houses and what styles do they represent?", a:"Moët & Chandon: approachable, consistent NV. Veuve Clicquot: full-bodied, yeasty Yellow Label. Krug: rich, multi-vintage Grande Cuvée (6+ years lees). Louis Roederer: balanced Cristal prestige cuvée. Bollinger: powerful, oxidative Special Cuvée (old vines Pinot Noir). Salon: single-vineyard Blanc de Blancs (only in top vintages). Grower Champagnes (RM): Selosse, Egly-Ouriet, Lassaigne — terroir-driven, small production.", ref:{ type:"search", label:"Champagne house comparison", url:"https://www.wine-searcher.com/find/champagne+krug+bollinger" } },
    { id:437, category:"Vinification", q:"What is 'native yeast' fermentation and why do some winemakers prefer it?", a:"Native (wild/indigenous) yeasts naturally present on grape skins and in the winery are used instead of commercial cultured yeast. Proponents argue native fermentation adds complexity, reflects terroir, and produces more 'authentic' wine. Risks: slower/stuck fermentation, less predictable results, potential off-flavors. Associated with natural wine movement and domaines like DRC, Leroy, and many Burgundy producers.", ref:null },
    { id:438, category:"Service & Pairing", q:"What is the correct way to present and pour wine at a fine dining table?", a:"Stand to guest's right. Present bottle with label facing guest — state producer, wine name, vintage. Wait for confirmation. Cut foil cleanly below second lip. Insert corkscrew centrally, extract cork without popping. Wipe lip. Pour 1–2 oz taste for host (not necessarily the person who ordered — whoever is hosting). Await approval. Serve ladies first (traditionally), then gentlemen, host last. Never fill more than one-third of glass.", ref:null },
    { id:439, category:"Labels & Law", q:"What is a 'Premier Cru' in Burgundy and how many are there?", a:"Premier Cru (1er Cru) is Burgundy's second-highest classification after Grand Cru. There are approximately 635 Premier Cru vineyards in Burgundy. Labels show the village name plus the vineyard name (e.g., Gevrey-Chambertin Les Cazetiers). They produce wines of significant quality and complexity between village-level and Grand Cru. Famous examples: Chambolle-Musigny Les Amoureuses, Puligny-Montrachet Les Pucelles, Volnay Clos des Chênes.", ref:{ type:"search", label:"Premier Cru Burgundy bottles", url:"https://www.wine-searcher.com/find/burgundy+premier+cru" } },
  ],
  cs2: [
    { id:501, category:"Regions", q:"Name and locate the 10 principal wine-growing regions of France.", a:"Bordeaux, Burgundy, Champagne, Alsace, Loire Valley, Rhône Valley, Languedoc-Roussillon, Provence, Jura/Savoie, Southwest France.", ref:{ type:"map", label:"France wine regions map", url:"https://www.winespectator.com/images/site/learn/maps/france_map_lg.gif" } },
    { id:502, category:"Grapes & Varieties", q:"What grapes are permitted in Châteauneuf-du-Pape?", a:"Up to 13 varieties (red and white). Dominants: Grenache, Syrah, Mourvèdre (GSM). Others include Cinsault, Clairette, Roussanne, Vaccarèse, Counoise.", ref:{ type:"search", label:"CDP bottles", url:"https://www.wine-searcher.com/find/chateauneuf+du+pape" } },
    { id:503, category:"Tasting", q:"Describe the systematic approach to identifying Chardonnay in a blind tasting.", a:"Color: medium gold. Nose: yellow apple, pear, citrus, tropical (warm); butter, cream, vanilla (oak); toast, hazelnut (aged). Palate: medium-high acidity, full body, long finish. Look for MLF (buttery) and oak treatment.", ref:null },
    { id:504, category:"Service & Pairing", q:"Classic pairing for Sauternes?", a:"Sauternes with Roquefort cheese (classic sweet/salty pairing). Also: foie gras, fruit-based desserts. The sweetness and acidity of Sauternes balance the rich fat and salt.", ref:null },
    { id:505, category:"Labels & Law", q:"Explain the German Prädikatswein hierarchy.", a:"In order of increasing sugar/ripeness: Kabinett → Spätlese → Auslese → Beerenauslese (BA) → Eiswein → Trockenbeerenauslese (TBA). Higher Prädikats allow more sweetness and command higher prices.", ref:null },
    { id:506, category:"Regions", q:"Describe the key wine appellations of the Loire Valley.", a:"Upper Loire (Centre): Sancerre and Pouilly-Fumé (Sauvignon Blanc, flint/mineral). Touraine: Vouvray and Montlouis (Chenin Blanc — dry to sweet), Chinon and Bourgueil (Cabernet Franc). Anjou-Saumur: Savennières (dry Chenin Blanc), Bonnezeaux/Quarts de Chaume (sweet Chenin), Saumur-Champigny (Cabernet Franc). Pays Nantais (near the Atlantic): Muscadet (Melon de Bourgogne, sur lie).", ref:{ type:"map", label:"Loire Valley map", url:"https://www.wine-searcher.com/regions/loire-valley" } },
    { id:507, category:"Grapes & Varieties", q:"Describe Sangiovese's key characteristics and regional expressions.", a:"High acidity, medium-high tannin, medium body, red/sour cherry, tomato leaf, dried herbs, leather. In Chianti Classico: earthy, mineral, bright cherry. In Brunello di Montalcino: more concentrated, structured, longer lived. In Morellino di Scansano: more rustic and fruit-forward.", ref:{ type:"search", label:"Sangiovese bottles", url:"https://www.wine-searcher.com/find/sangiovese" } },
    { id:508, category:"Tasting", q:"How would you identify Cabernet Sauvignon vs. Merlot in a blind tasting?", a:"Cabernet: deeper ruby-purple, firm/grippy tannins, cassis/blackcurrant/tobacco, cedar, full body, higher structure. Merlot: more approachable tannins, softer texture, plum/mocha/chocolate notes, slightly lower acidity, medium-full body. Cabernet = angular and structured; Merlot = rounder and plush.", ref:null },
    { id:509, category:"Vinification", q:"What is the difference between Prosecco's Charmat method and Champagne's traditional method?", a:"Charmat (Tank Method): secondary fermentation in pressurized tank. Less yeast contact, fresh fruit, lower cost, used for Prosecco, Lambrusco. Traditional Method: secondary fermentation in bottle, extended lees contact (15+ months), more complexity, yeast/bread notes, used for Champagne, Cava, Franciacorta.", ref:null },
    { id:510, category:"Regions", q:"Name the key zones of Rioja and describe their wine styles.", a:"Rioja Alta (northwest, Atlantic influence, elegant Tempranillo), Rioja Alavesa (smallest, similar style, some single-estate wines), Rioja Oriental/Baja (warmer, Mediterranean, higher Garnacha — riper, fuller).", ref:{ type:"map", label:"Rioja map", url:"https://www.wine-searcher.com/regions/rioja" } },
    { id:511, category:"Service & Pairing", q:"What wine would you recommend with a classic French onion soup?", a:"A rich, full-bodied white with good acidity to cut through the cheese and complement the savory sweetness: white Burgundy (Meursault), white Rhône (Marsanne/Roussanne blend), or a dry Alsatian Pinot Gris. Alternatively, a light earthy Pinot Noir.", ref:null },
    { id:512, category:"Labels & Law", q:"Explain the classification of St-Émilion and how it differs from the Médoc.", a:"St-Émilion is reclassified periodically. Three tiers: Premier Grand Cru Classé A (Ausone, Cheval Blanc), Premier Grand Cru Classé B, Grand Cru Classé. Unlike the static 1855 Médoc classification, St-Émilion's classification is theoretically meritocratic and revisable.", ref:null },
    { id:513, category:"Tasting", q:"Describe the aroma and flavor profile of Viognier.", a:"Stone fruit (peach, apricot, nectarine), honeysuckle and violet florals, white pepper and ginger spice, full body with low-medium acidity. Rich and often unctuous texture. Key: it smells sweet but is usually dry. Regions: Condrieu (Northern Rhône), Château-Grillet, Australia (Yalumba).", ref:{ type:"search", label:"Condrieu / Viognier bottles", url:"https://www.wine-searcher.com/find/condrieu" } },
    { id:514, category:"Vinification", q:"How is Eiswein (Ice Wine) made and what makes it rare?", a:"Grapes are left on the vine until temperatures drop to –7 to –8°C (mid-winter). Frozen grapes are picked and pressed immediately while still frozen — ice crystals remain behind, concentrating sugars and acids dramatically. Very small yields, labor-intensive, weather-dependent. Germany, Austria, Canada (VQA Ice Wine).", ref:null },
    { id:515, category:"Regions", q:"Describe the terroir and wine style of Priorat, Spain.", a:"Rugged mountainous region in Catalonia with llicorella (slate/quartz) soils. Very low-yielding old-vine Garnacha and Cariñena (Carignan). Produces intense, concentrated, mineral, dark-fruited wines with high alcohol. DOCa classification (like Rioja). Producers: Álvaro Palacios, Clos Mogador.", ref:{ type:"map", label:"Priorat map", url:"https://www.wine-searcher.com/regions/priorat" } },
    { id:516, category:"Grapes & Varieties", q:"What is Albariño and where is it from?", a:"Aromatic white grape of Rías Baixas DO (Galicia, northwestern Spain). Characteristics: high acidity, medium-light body, peach, apricot, citrus (lime/lemon), saline/maritime minerality. Classic pairing with Galician seafood.", ref:{ type:"search", label:"Albariño bottles", url:"https://www.wine-searcher.com/find/albarino" } },
    { id:517, category:"Service & Pairing", q:"How does a sommelier handle a guest returning a wine as faulty?", a:"Always accept the bottle graciously without argument. Evaluate the wine discreetly. If corked/oxidized/genuinely faulty: replace immediately with no charge. If the wine is sound (guest dislikes the style): offer a replacement diplomatically — guest preference is paramount.", ref:null },
    { id:518, category:"Labels & Law", q:"What information must appear on a wine label in the United States?", a:"Brand name, class/type designation, alcohol content (actual or range), net contents, name and address of bottler/importer, country of origin, government health warning statement, and sulfite declaration if applicable. Vintage and variety are optional but common.", ref:null },
    { id:519, category:"Regions", q:"What are the key wine regions and styles of Australia?", a:"Barossa Valley (Shiraz — rich, jammy, powerful; Eden Valley — cool Riesling). Clare Valley (Riesling). Coonawarra (Cabernet Sauvignon on terra rossa soil). Margaret River (Bordeaux blends). Hunter Valley (Semillon, Shiraz). Yarra Valley/Mornington Peninsula (cool-climate Pinot Noir, Chardonnay).", ref:{ type:"map", label:"Australia wine regions", url:"https://winefolly.com/learn/wine-region-maps/" } },
    { id:520, category:"Tasting", q:"Describe the aromas and structure of a classic Rioja Reserva.", a:"Medium ruby color with garnet/brick rim (age-related). Nose: dried cherry, leather, tobacco, vanilla/coconut (American oak), dried herbs. Palate: medium tannin (softened by age), medium-high acidity, medium-full body. American oak spice + tertiary development are the hallmarks.", ref:null },
    { id:521, category:"Regions", q:"Describe the key wine regions and styles of Argentina beyond Malbec.", a:"Mendoza also excels in Cabernet Sauvignon (Luján de Cuyo), Torrontés (Cafayate, Salta — floral/aromatic white), Bonarda (everyday red), and Chardonnay (Valle de Uco). Patagonia (Neuquén, Río Negro): cool-climate Pinot Noir and Malbec. Salta (Cafayate): world's highest-altitude vineyards — intense Torrontés and Malbec.", ref:{ type:"map", label:"Argentina wine regions", url:"https://www.wine-searcher.com/regions/argentina" } },
    { id:522, category:"Grapes & Varieties", q:"Describe the key characteristics of Grüner Veltliner.", a:"Austria's signature white grape. White pepper and green herb hallmark. Also: grapefruit, lemon, green apple, celery, stone fruit (richer styles). High acidity, medium-full body. Wachau, Kamptal, and Kremstal are the top regions. Smaragd tier rivals top white Burgundy in richness. Excellent food wine for spicy cuisine and vegetables.", ref:{ type:"search", label:"Grüner Veltliner bottles", url:"https://www.wine-searcher.com/find/gruner+veltliner" } },
    { id:523, category:"Tasting", q:"How do you identify Gewurztraminer in a blind tasting?", a:"Deeply colored (pale gold to amber-gold). Explosive aromatic profile: lychee, rose petal, Turkish delight, ginger, cinnamon. Low acidity, full body, slightly oily texture. Can be dry (Alsace), off-dry, or sweet (Vendanges Tardives). The combination of intense floral/spice aromatics with low acidity is unmistakable. Alsace is the benchmark region.", ref:{ type:"search", label:"Gewurztraminer bottles", url:"https://www.wine-searcher.com/find/gewurztraminer+alsace" } },
    { id:524, category:"Vinification", q:"What is skin contact time (maceration) and how does it affect wine style?", a:"In red winemaking, maceration is the period when juice contacts grape skins during and after fermentation. Short maceration (5–7 days): lighter color, softer tannins, more fruit-forward (early-drinking style). Long maceration (3–4 weeks): deep color, firm/grippy tannins, greater structure and aging potential (Barolo, structured Bordeaux).", ref:null },
    { id:525, category:"Service & Pairing", q:"What wine would you pair with a rich lobster bisque?", a:"A full-bodied, oaked white wine with good acidity and texture: white Burgundy (Meursault or Puligny-Montrachet), Viognier from Condrieu, white Rhône (Hermitage Blanc), or a rich California Chardonnay (Kistler, Ramey). The wine's weight, creaminess, and acidity should match and cut through the bisque's richness.", ref:null },
    { id:526, category:"Tasting", q:"How would you identify a wine made from Pinot Gris/Pinot Grigio in a blind tasting?", a:"Pinot Grigio (Italy): pale lemon, light body, crisp acidity, neutral pear/apple/citrus, clean and simple. Pinot Gris (Alsace): deeper gold, full body, low acidity, rich stone fruit (peach, apricot), spice (ginger), waxy texture, often off-dry. Same grape — radically different styles depending on winemaking approach and climate. Body and richness are the key differentiators.", ref:null },
    { id:527, category:"Regions", q:"Describe the wine regions and styles of the Languedoc-Roussillon.", a:"France's largest wine-producing region (southern France, Mediterranean coast). Traditionally known for bulk wine, now producing quality wines: Pic Saint-Loup (red GSM blends), Faugères (schist soils, Syrah/Grenache/Mourvèdre), Corbières, Minervois, Roussillon (Grenache-based reds and vins doux naturels — Maury, Banyuls, Rivesaltes). Excellent value across all styles.", ref:{ type:"map", label:"Languedoc-Roussillon map", url:"https://www.wine-searcher.com/regions/languedoc-roussillon" } },
    { id:528, category:"Viticulture", q:"What is 'dry farming' and why does it matter for wine quality?", a:"Dry farming means growing vines without irrigation, relying solely on natural rainfall and deep root systems. Vines must dig deep for water, which stresses the vine, concentrates fruit flavors, and produces lower yields. Common in traditional European regions and increasingly prized in California and Australia. Opposite of irrigated viticulture. Associated with old-vine character.", ref:null },
    { id:529, category:"Vinification", q:"What is 'extended maceration' and which wines benefit from it?", a:"Extended maceration involves leaving red wine on its skins for weeks to months after fermentation is complete. The alcohol (now present) extracts different tannin types than during fermentation — potentially softer, more polymerized tannins over time. Benefits wines designed for very long aging: Barolo, structured Cabernet Sauvignon. Risk: can produce astringent, drying tannins if not managed carefully.", ref:null },
    { id:530, category:"Service & Pairing", q:"What classic wine would you recommend with a cheese course featuring aged Comté?", a:"Aged Comté (nutty, crystalline, complex) pairs beautifully with: white Burgundy (Meursault — hazelnut and apple mirror Comté's nuttiness), aged Champagne (yeasty complexity + acidity cut through fat), Jura whites (Savagnin/Chardonnay from the same region as Comté — classic regional pairing), or an aged Riesling Spätlese. The wine should have enough body and complexity to match the cheese's intensity.", ref:null },
    { id:531, category:"Regions", q:"Describe the wine styles and key appellations of Provence, France.", a:"Provence (southeastern France, Mediterranean coast) is best known for dry rosé — pale salmon-colored, crisp, dry, with strawberry, citrus, herbal (garrigue/lavender/thyme) notes. Key AOCs: Côtes de Provence (largest, mostly rosé), Bandol (structured rosé and powerful Mourvèdre-based reds — Château Pibarnon, Domaine Tempier), Cassis (whites from Clairette/Marsanne). Provence accounts for ~40% of French rosé production.", ref:{ type:"map", label:"Provence wine map", url:"https://www.wine-searcher.com/regions/provence" } },
    { id:532, category:"Tasting", q:"How do you identify Malbec from Mendoza vs. Cahors (France) in a blind tasting?", a:"Mendoza Malbec: deep purple-black, plum/blackberry/violet/chocolate, velvety tannins, medium acidity, often new French oak (vanilla/cedar), high alcohol (14%+), round and approachable. Cahors Malbec (Auxerrois): darker/more tannic, earthy/iron/black fruit, more austere and angular, lower alcohol, less new oak. Mendoza = lush and fruit-driven; Cahors = structured and rustic. Body and tannin texture are key differentiators.", ref:null },
    { id:533, category:"Grapes & Varieties", q:"Describe the key characteristics of Mourvèdre/Monastrell.", a:"Thick-skinned red grape requiring heat and sun to ripen fully. Character: very dark color, high tannin, savory/meaty/gamey notes, dark fruit (blackberry, prune), pepper, leather, iron. Low acidity. Key regions: Bandol (Provence — dominant variety, long-aging reds), Châteauneuf-du-Pape (GSM blending), Jumilla and Yecla (Spain — Monastrell), California and Australia. Can be rustic young, magnificent with age.", ref:{ type:"search", label:"Bandol / Mourvèdre bottles", url:"https://www.wine-searcher.com/find/bandol+mourvedre" } },
    { id:534, category:"Vinification", q:"What is 'chapitalization' and when is it used?", a:"Chapitalization is the addition of sugar to grape must before or during fermentation to increase the final alcohol level. It does NOT add sweetness — the sugar is fully converted to alcohol by yeast. Legal in cool climates where grapes may not fully ripen (Burgundy, Champagne, Germany in some years). Illegal in warm climates (California, southern Italy, southern Spain) where natural sugar levels are already high. Regulated by EU wine law.", ref:null },
    { id:535, category:"Service & Pairing", q:"What wine pairs with a classic roast chicken?", a:"Roast chicken is a versatile pairing anchor. White: white Burgundy (Meursault or Puligny-Montrachet) — richness and acidity match the fat and herbs. Viognier (Condrieu) — floral/stone fruit complements herb roasting. Red: Pinot Noir (Burgundy or Oregon) — earthiness and red fruit complement without overwhelming. Also: Chardonnay (unoaked, Chablis style) for a leaner bird; aged Rioja for herb-roasted versions.", ref:null },
    { id:536, category:"Regions", q:"Describe the wine regions and styles of the Wachau, Austria.", a:"The Wachau is a steep, terraced valley of the Danube River west of Vienna, producing Austria's most prestigious Riesling and Grüner Veltliner. Three quality tiers (Vinea Wachau): Steinfeder (lightest, max 11.5% abv), Federspiel (medium, 11.5–12.5% abv), Smaragd (richest, min 12.5% abv, equivalent to Grand Cru quality). Gneiss and granite soils give mineral, precise wines of extraordinary aging potential. Key producers: F.X. Pichler, Emmerich Knoll, Rudi Pichler, Domäne Wachau.", ref:{ type:"map", label:"Wachau map", url:"https://www.wine-searcher.com/regions/wachau" } },
    { id:537, category:"Grapes & Varieties", q:"Describe the sensory profile of Muscat Blanc à Petits Grains and its key wine styles.", a:"Muscat Blanc à Petits Grains is the noblest Muscat variety — the rare grape that smells and tastes grapey/floral when made into wine. Aromas: fresh grapes, orange blossom, rose, apricot, ginger. Wines: Asti Spumante (light sweet sparkling, Piedmont), Moscato d'Asti (frizzante, 5.5% abv), Muscat de Beaumes-de-Venise (vin doux naturel, Southern Rhône), Muscat d'Alsace (dry, aromatic). The touchstone of aromatic white wine.", ref:{ type:"search", label:"Muscat wines", url:"https://www.wine-searcher.com/find/muscat+beaumes+venise" } },
    { id:538, category:"Tasting", q:"How do you systematically distinguish between primary, secondary, and tertiary aromas in a CMS tasting?", a:"Primary aromas come directly from the grape: fresh fruit (citrus, stone fruit, berry), floral (rose, violet), herbal (grass, bell pepper), and spice (black pepper). Secondary aromas come from fermentation: bread/brioche (yeast autolysis), butter/cream (MLF). Tertiary aromas develop from aging in oak or bottle: vanilla/cedar/toast (oak), leather/tobacco/dried fruit/petrol/mushroom (bottle age). A wine showing all three is fully developed.", ref:null },
    { id:539, category:"Vinification", q:"What is 'riddling' (remuage) in Champagne production and how has it evolved?", a:"Riddling is the gradual rotation and tilting of bottles (over 6–8 weeks traditionally) so that spent yeast sediment from the secondary fermentation collects in the neck. Traditionally done by hand on pupitres (A-frame racks) by skilled remueurs who turn each bottle 1/8 turn daily. Modern production uses gyropalettes — large steel cages that mechanically riddle thousands of bottles simultaneously in 1–2 weeks, dramatically reducing cost while matching quality.", ref:null },
    { id:540, category:"Service & Pairing", q:"What wine pairs best with a classic beef Wellington?", a:"Beef Wellington (beef tenderloin in mushroom duxelles and puff pastry) calls for a wine that can match its richness and earthy mushroom character. Best choices: aged Pomerol or Saint-Émilion (Merlot-dominant Bordeaux — plush, earthy, complements the mushroom); Barolo or Barbaresco (Nebbiolo — earthiness, truffle notes mirror duxelles); Napa Cabernet Sauvignon (structure for the beef, body for pastry richness); aged Burgundy Grand Cru if budget allows.", ref:null },
  ],
  cs3: [
    { id:601, category:"Tasting", q:"Describe the deductive approach to identifying Pinot Noir vs. Nebbiolo in a blind tasting.", a:"Pinot Noir: translucent ruby, red fruit (cherry, raspberry), earth/forest floor, silky tannins, medium body. Nebbiolo: garnet with orange rim, tar/roses/leather, red fruit, very high acidity and tannin, angular structure. Nebbiolo far more structured.", ref:null },
    { id:602, category:"Regions", q:"Name the most important Grand Cru vineyards of the Côte de Nuits.", a:"The Côte de Nuits has 24 Grand Crus. Key ones by village: Gevrey-Chambertin (Chambertin, Chambertin-Clos de Bèze, plus seven other '-Chambertin' crus), Morey-Saint-Denis (Clos de la Roche, Clos Saint-Denis, Clos de Tart), Chambolle-Musigny (Musigny, Bonnes-Mares), Vougeot (Clos de Vougeot), Flagey-Échézeaux (Échézeaux, Grands Échézeaux) and Vosne-Romanée (Romanée-Conti, La Tâche, Richebourg, La Romanée, Romanée-Saint-Vivant, La Grande Rue). Almost all are red Pinot Noir; Musigny also makes a little white.", ref:{ type:"map", label:"Côte de Nuits map", url:"https://www.burgundy-report.com/maps/" } },
    { id:603, category:"Viticulture", q:"What is the distinction between Botrytis cinerea as noble rot vs. grey rot?", a:"Noble rot (Botrytis) requires initial humidity for spore germination, then warm/dry conditions to concentrate sugars without destroying fruit. Grey rot occurs under continuously wet conditions, destroying the grape. Noble rot is essential for Sauternes, German TBA, and Tokaji Aszú.", ref:null },
    { id:604, category:"Vinification", q:"Describe the Solera system used in Sherry production.", a:"A fractional blending system of barrels arranged in tiers. Wine drawn from the lowest tier (oldest) is refreshed by younger wine from tiers above. Ensures consistency and averages age across vintages. No more than 1/3 drawn per year.", ref:{ type:"search", label:"Sherry bottles", url:"https://www.wine-searcher.com/find/sherry+fino+manzanilla" } },
    { id:605, category:"Regions", q:"What are the key styles of Sherry and their production method?", a:"Fino/Manzanilla: biologically aged under flor (yeast veil), pale, dry, saline. Amontillado: flor dies, oxidatively aged, nutty/amber. Oloroso: oxidative aging, no flor, rich/dark. Palo Cortado: rare, between Amontillado and Oloroso. PX/Moscatel: sweet varieties.", ref:null },
    { id:606, category:"Service & Pairing", q:"Describe proper decanting technique for an old Bordeaux with sediment.", a:"Stand bottle upright 24h to settle sediment. Open carefully. Pour slowly over candle/light in single continuous pour. Stop when sediment reaches neck. Do not shake or rush. Decant 30–60 min before service for aeration.", ref:null },
    { id:607, category:"Tasting", q:"How do you distinguish Northern Rhône Syrah from Australian Shiraz in a blind tasting?", a:"Northern Rhône Syrah (Hermitage, Crozes-Hermitage): dark ruby, olive/smoked meat/violets/pepper, medium-full tannin, higher acidity, more savory and mineral. Australian Shiraz (Barossa): deeper color, ripe blackberry/plum/chocolate/licorice, lower acidity, fuller body, oak influence. Climate is the key differentiator.", ref:{ type:"search", label:"Barossa Shiraz bottles", url:"https://www.wine-searcher.com/find/barossa+shiraz" } },
    { id:608, category:"Regions", q:"Describe the geography and wine styles of New Zealand.", a:"Marlborough (South Island): world benchmark Sauvignon Blanc; also Pinot Noir. Central Otago (world's southernmost wine region): intense, elegant Pinot Noir. Hawke's Bay (North Island): Bordeaux varieties, Syrah. Martinborough: Pinot Noir. Waipara/Canterbury: Riesling, Pinot Noir.", ref:{ type:"map", label:"New Zealand wine map", url:"https://winefolly.com/learn/wine-region-maps/" } },
    { id:609, category:"Viticulture", q:"Explain the impact of soil types on wine character — compare limestone, clay, and schist.", a:"Limestone: good drainage, retains some moisture, imparts mineral/chalky character (Chablis, Champagne). Clay: water-retaining, cooler, earlier harvest, can give weight/structure (Pomerol). Schist/slate: poor, well-drained, heat-absorbing, encourages deep roots, minerality and concentration (Mosel, Douro, Priorat).", ref:null },
    { id:610, category:"Vinification", q:"What is reduction in wine and how is it addressed?", a:"Reduction occurs when wine develops sulfurous off-aromas (struck match, rubber, rotten egg, onion) due to limited oxygen exposure. Address: splash decanting/aeration, which allows the volatile compounds to dissipate. Severe cases may require copper fining.", ref:null },
    { id:611, category:"Regions", q:"Describe the key wine regions and grape varieties of Austria.", a:"Grüner Veltliner (Austria's signature white — white pepper, green herbs, citrus, mineral): Wachau, Kamptal, Kremstal. Riesling: Wachau (Smaragd = richest, dry). Blaufränkisch (red): Burgenland (spice, sour cherry, pepper). Zweigelt: Austria's most-planted red. Wachau quality tiers: Steinfeder, Federspiel, Smaragd.", ref:{ type:"map", label:"Austria wine map", url:"https://www.wine-searcher.com/regions/austria" } },
    { id:612, category:"Tasting", q:"How do you approach identifying a wine as Old World vs. New World in a blind tasting?", a:"Old World indicators: higher acidity, lower alcohol, earthy/savory/mineral notes, restrained fruit, herbal character, more tannin structure. New World indicators: richer fruit intensity, higher alcohol, fuller body, riper tannins, more obvious oak, less earthiness. Climate and winemaker style can blur the line.", ref:null },
    { id:613, category:"Service & Pairing", q:"How do you build a wine list for a fine dining restaurant?", a:"Structure by Old/New World or by region. Balance price points across each tier. Feature a sommelier's selection/value section. Include half-bottles and magnums. Offer by-the-glass program. Ensure representation across red, white, sparkling, sweet, fortified. Rotate seasonally. Keep depth in key categories (Burgundy, Barolo, Bordeaux).", ref:null },
    { id:614, category:"Labels & Law", q:"What are the legal requirements for DOCG Amarone della Valpolicella?", a:"DOCG since 2010. Grapes: minimum 45% Corvina/Corvinone, max 30% Rondinella. Appassimento required: minimum 90 days drying. Minimum alcohol: 14%. Minimum aging: 2 years (4 for Riserva). Maximum residual sugar: 12 g/L (to be classified dry).", ref:null },
    { id:615, category:"Regions", q:"What are the principal wine-producing regions of South Africa?", a:"Stellenbosch (Cabernet Sauvignon, Bordeaux blends — Kanonkop, Meerlust). Swartland (Chenin Blanc, Rhône varieties — Eben Sadie). Constantia (historic Muscat; modern Sauvignon Blanc). Franschhoek (Bordeaux, Chardonnay). Walker Bay/Hemel-en-Aarde (cool: Pinot Noir, Chardonnay). Pinotage: SA's signature variety.", ref:{ type:"map", label:"South Africa wine map", url:"https://www.wine-searcher.com/regions/south-africa" } },
    { id:616, category:"Grapes & Varieties", q:"Describe Malbec's sensory profile and Mendoza's key sub-regions.", a:"Deep purple color, plum/blackberry/violet, milk chocolate, tobacco. Lower tannin than Cabernet, higher acidity at altitude. Mendoza sub-regions: Luján de Cuyo (classic, structured). Maipú (hotter, more traditional). Valle de Uco (high altitude 900–1500m: Tupungato, San Carlos — freshness, mineral, more Burgundian).", ref:{ type:"search", label:"Mendoza Malbec bottles", url:"https://www.wine-searcher.com/find/mendoza+malbec" } },
    { id:617, category:"Vinification", q:"Explain the difference between Vintage Port, LBV, Colheita, and Tawny Port.", a:"Vintage Port: declared years, 2 years cask, aged in bottle for decades (sediment forms). LBV: single vintage, 4–6 years in cask, filtered or unfiltered (Traditional LBV — sediment, needs decanting). Colheita: single-vintage Tawny aged minimum 7 years in cask. Tawny (10/20/30/40 year): blend of years, oxidative amber/nutty style.", ref:null },
    { id:618, category:"Tasting", q:"How do you use viscosity and legs (tears) as tasting clues?", a:"Legs/tears form due to alcohol's lower surface tension than water (Marangoni effect). Slow, thick, wide tears = higher alcohol and/or residual sugar. Thin, fast tears = lighter, lower-alcohol wine. A useful preliminary indicator but not diagnostic on its own — always confirm on the palate.", ref:null },
    { id:619, category:"Regions", q:"Describe the Tokaj wine region of Hungary and its classification system.", a:"Northeast Hungary. Volcanic tufa soil (nyirok). Key grape: Furmint (80%+), Hárslevelű. Styles: Tokaji Aszú (botrytized berries measured in puttonyos: 5 and 6 puttonyos = 120–150+ g/L RS). Aszú Eszencia (rarest, near-syrup). Dry Furmint: increasingly important. Classified First to Fifth Growth vineyard sites.", ref:{ type:"map", label:"Tokaj region map", url:"https://www.wine-searcher.com/regions/tokaj" } },
    { id:620, category:"Service & Pairing", q:"What wine pairs with sushi and omakase dining?", a:"Champagne or sparkling wine (acidity and effervescence cleanse and refresh). White Burgundy/Chablis (mineral/saline matches soy/wasabi/seafood). Sake (fermented rice — umami on umami). Dry Riesling (acidity + petrol note with fatty fish). Avoid heavily oaked or tannic reds — they clash with delicate fish.", ref:null },
    { id:621, category:"Viticulture", q:"What is green harvesting (vendange en vert) and when is it used?", a:"Dropping unripe grape clusters in early summer (before véraison) to reduce yield and concentrate the vine's energy into fewer, higher-quality bunches. Practiced in high-vigor sites to control overproduction. Results in more concentrated flavors, better color, and improved structure.", ref:null },
    { id:622, category:"Tasting", q:"How do you approach identifying Riesling vs. Chenin Blanc in a blind tasting?", a:"Both: high acidity, can range from bone dry to lusciously sweet. Riesling: petrol/kerosene note (TDN) in aged wines, slate/mineral, lime zest, apple, honey (if sweet), lower body. Chenin Blanc: chamomile, quince, hay, waxy texture, more body, lanolin, apple/pear, never develops the petrol note. Chenin has more body and texture; Riesling has more linear acidity.", ref:null },
    { id:623, category:"Regions", q:"Describe the key wine regions and styles of the Finger Lakes, New York.", a:"Cool continental climate on Seneca and Cayuga Lakes (thermal regulation prevents extreme cold). Benchmark wines: Riesling (dry to botrytized — Dr. Konstantin Frank, Red Newt, Hermann J. Wiemer), Cabernet Franc (increasingly serious), Chardonnay. The Finger Lakes is considered the New World's best source of dry and off-dry Riesling.", ref:{ type:"map", label:"Finger Lakes wine map", url:"https://www.wine-searcher.com/regions/finger-lakes" } },
    { id:624, category:"Viticulture", q:"What is 'selection massale' vs. 'clonal selection' and why does it matter for wine quality?", a:"Clonal selection: propagating a single superior vine's cuttings — produces uniform, predictable results. Massale (mass selection): taking cuttings from many old vines in the same vineyard — captures genetic diversity. Massale produces more complex, nuanced wine and better preserves old-vine character. DRC and top Burgundy domaines use massale selection.", ref:null },
    { id:625, category:"Vinification", q:"What is 'délestage' (rack and return) and how does it differ from other extraction techniques?", a:"Délestage involves completely draining all the juice from the fermenting tank, allowing the cap of skins to fall and break apart, then pumping the juice back over the reconstituted cap. It extracts less harsh tannin than punch-down but more than gentle pump-over, while also helping to aerate the fermentation. Useful for thick-skinned varieties.", ref:null },
    { id:626, category:"Regions", q:"Describe the key wines and producers of Châteauneuf-du-Pape.", a:"Southern Rhône's most prestigious appellation. Red: dominant Grenache blended with Syrah, Mourvèdre, others — warm, full-bodied, 14.5%+ abv. White: Grenache Blanc, Clairette, Roussanne. Key estates: Château Rayas (100% Grenache), Château Beaucastel (all 13 varieties), Château La Nerthe, Pégaü, Château Fortia (historic). Sandy galets roulés (rounded stones) retain heat.", ref:{ type:"search", label:"Châteauneuf-du-Pape bottles", url:"https://www.wine-searcher.com/find/chateauneuf+du+pape" } },
    { id:627, category:"Regions", q:"Describe the key wine styles of Burgundy's Côte Chalonnaise and Mâconnais.", a:"Côte Chalonnaise: Mercurey (Pinot Noir — good value, earthy), Givry (Pinot Noir — elegant, lighter), Rully (Chardonnay and Crémant de Bourgogne — fresh, bright), Montagny (Chardonnay — mineral). Mâconnais: Mâcon-Villages (Chardonnay — easy, unoaked), Pouilly-Fuissé (richer, some oak), Saint-Véran (leaner, mineral). Both offer Burgundy character at more accessible prices than Côte d'Or.", ref:{ type:"map", label:"Côte Chalonnaise and Mâconnais map", url:"https://www.burgundy-report.com/maps/" } },
    { id:628, category:"Grapes & Varieties", q:"Describe the sensory profile and key regions of Cabernet Franc.", a:"Medium ruby, lighter than Cabernet Sauvignon. Aromas: green pepper/graphite/violet/tobacco (cooler climates), red fruit (cherry, raspberry), cedar, herbal. Medium tannin, high acidity. Cooler climates: Loire Valley (Chinon, Bourgueil, Saumur-Champigny — benchmark dry reds). Right Bank Bordeaux: blending grape. Also: Friuli (Italy), Napa Valley. Ages beautifully. Chinon is the purest expression.", ref:{ type:"search", label:"Cabernet Franc/Chinon bottles", url:"https://www.wine-searcher.com/find/chinon+cabernet+franc" } },
    { id:629, category:"Viticulture", q:"What is the role of cover crops in sustainable viticulture?", a:"Cover crops are plants grown between vine rows (grasses, legumes, wildflowers). Benefits: prevent erosion, improve soil structure, fix nitrogen (legumes), encourage beneficial insect biodiversity, compete with vines to control vigor, and increase organic matter. In wet climates: manage water absorption. In dry climates: can compete for water (must be managed). Central to organic and biodynamic farming.", ref:null },
    { id:630, category:"Tasting", q:"How do you distinguish Tempranillo from Grenache/Garnacha in a blind tasting?", a:"Tempranillo: medium ruby, strawberry/cherry/leather/tobacco, medium-high acidity, medium tannin, earthy/savory, often shows American oak (vanilla/coconut in Rioja), ages gracefully. Grenache: lighter color (pale ruby), high alcohol, low tannin, low acidity, red fruit/kirsch/garrigue, warm/spicy, can show oxidative notes (orange peel). Grenache = rounder, higher alcohol, paler; Tempranillo = more structured, earthy, darker fruit.", ref:null },
    { id:631, category:"Service & Pairing", q:"How should a sommelier handle a situation where the wine list has a significant gap in by-the-glass offerings?", a:"First, acknowledge the gap without defensiveness. Offer half-bottle options if available. Suggest the guest try a taste of a relevant bottle before committing. Consider opening a full bottle if two or more guests at the table share interest — offer by the taste/half glass. Use this as feedback for the beverage director to update the BTG program. The goal is always to find the best solution for the guest's experience.", ref:null },
    { id:632, category:"Regions", q:"Describe the key wine styles of Alsace and the Grand Cru system.", a:"Alsace (northeastern France, sheltered by Vosges Mountains): dry to very sweet whites from aromatic varieties. The 51 Grand Cru sites must use only Riesling, Gewurztraminer, Pinot Gris, or Muscat. Key Grand Crus: Schlossberg (granite, elegant Riesling), Rangen (volcanic, Gewurztraminer), Brand, Hengst. Vendanges Tardives (VT = late harvest) and Sélection de Grains Nobles (SGN = botrytized, sweet) are special designations. Best producers: Zind-Humbrecht, Trimbach, Weinbach.", ref:{ type:"map", label:"Alsace Grand Cru map", url:"https://www.wine-searcher.com/regions/alsace" } },
    { id:633, category:"Tasting", q:"How do you approach identifying a wine as Grenache-dominant vs. Syrah-dominant in a Southern Rhône blind tasting?", a:"Grenache-dominant (Châteauneuf-du-Pape, Gigondas): pale-medium ruby, high alcohol (14.5%+), low tannin, low acidity, red fruit/kirsch/garrigue/orange peel, warm and generous. Syrah-dominant component (if present): darker color, adds structure, pepper, meat, and violet to the blend. A very pale ruby color with high alcohol and low tannin in a Southern Rhône context almost always indicates Grenache dominance.", ref:null },
    { id:634, category:"Viticulture", q:"What is 'physiological ripeness' in white grapes and why is harvest timing critical?", a:"In white grapes, physiological ripeness means seeds are brown (not green), skins are soft and easily broken, stems begin to lignify, and the juice shows full aromatic development beyond simple sugar accumulation. Harvest too early: high acidity, green flavors, underripe aromas. Too late: low acidity, flabby, overripe/jammy, loss of variety-specific aromatics. White varieties have a narrower window than reds — often just days separate optimal from overripe.", ref:null },
    { id:635, category:"Vinification", q:"Describe the production of Recioto della Valpolicella and how it differs from Amarone.", a:"Both use appassimento-dried Corvina/Rondinella grapes. Recioto: fermentation is stopped early (by cold, addition of SO2, or filtering) while significant residual sugar remains — producing a sweet, rich red (60–90 g/L RS) with dried cherry, chocolate, and tobacco. Amarone: fermented to near dryness (max 12 g/L RS). Recioto is therefore the sweet counterpart to Amarone's power. Recioto is also produced in a white version (Recioto di Soave — from Garganega).", ref:{ type:"search", label:"Recioto della Valpolicella bottles", url:"https://www.wine-searcher.com/find/recioto+valpolicella" } },
    { id:636, category:"Service & Pairing", q:"Describe the ideal pairing approach for a classic Thanksgiving dinner.", a:"Thanksgiving features diverse flavors: turkey (mild, fatty), stuffing (herby, savory), sweet potato (sweet), cranberry (tart), gravy (umami-rich). Best wine strategies: off-dry Riesling (bridges sweet and savory), Pinot Noir (earthiness + red fruit complement turkey and mushroom stuffing), Beaujolais (light, fruity, low tannin, crowd-pleasing), dry Gewurztraminer (spice mirrors sweet potato and stuffing herbs). Avoid: high tannin Cabernet (overwhelms turkey), very oaky Chardonnay (competes with herb flavors).", ref:null },
    { id:637, category:"Tasting", q:"How do you use color rim variation to estimate a red wine's age in a blind tasting?", a:"As red wine ages, anthocyanin pigments degrade and polymerize. Young reds (0–3 years): deep purple-ruby to the rim, no color graduation. Developing (4–8 years): ruby-garnet center, slight tawny/orange at the rim. Aged (8–15+ years): garnet-tawny center, pronounced orange/brick rim. Very old wines: nearly tawny throughout. The width and intensity of the orange/brick rim is one of the most reliable visual aging indicators — always assess rim vs. core color difference.", ref:null },
    { id:638, category:"Regions", q:"Describe the key wine regions and styles of the Douro Valley for unfortified wines.", a:"The Douro Unfortified ('Douro DOC table wines') has transformed since the 1990s. Steep schist terraces, extreme heat (50°C+ in summer), and indigenous varieties (Touriga Nacional, Touriga Franca, Tinta Roriz/Aragonez, Tinta Barroca) produce powerful, concentrated reds. Sub-regions: Baixo Corgo (wetter, lighter), Cima Corgo (Port heartland, great table wine), Douro Superior (hottest, most remote). Top producers: Quinta do Crasto, Niepoort (Batuta), Ramos Pinto, Quinta Vale Meão.", ref:{ type:"map", label:"Douro Valley wine map", url:"https://www.wine-searcher.com/regions/douro" } },
    { id:639, category:"Viticulture", q:"What is 'cordon training' vs. 'cane pruning' and how does the choice affect wine quality?", a:"Cane pruning (Guyot): one or two long canes from last year's growth are retained and tied horizontally; all other wood is cut away. Lower, more consistent yields; ideal for cool climates (Burgundy, Champagne, Mosel). Cordon training (spur pruning): a permanent horizontal arm (cordon) is established with short spurs left each year. More productive, easier to mechanize, suited to warmer climates (Barossa, Rioja, Rhône). Cane pruning generally gives better quality; cordon suits quantity and efficiency.", ref:null },
    { id:640, category:"Vinification", q:"Explain the production of Rutherglen Muscat (Australian 'Sticky') and its classification system.", a:"Rutherglen Muscat (Victoria, Australia) is made from Muscat à Petits Grains Rouge (Brown Muscat), harvested at extreme ripeness, partially fermented then fortified, and aged in a solera-like system for years to decades. Four tiers: Rutherglen Muscat (youngest, freshest), Classic (more complexity), Grand (concentrated, 10+ years average age), Rare (oldest, thickest, most complex — some wine 50+ years old). Result: mahogany-colored, syrup-thick, raisin/toffee/coffee/orange peel elixirs.", ref:{ type:"search", label:"Rutherglen Muscat bottles", url:"https://www.wine-searcher.com/find/rutherglen+muscat" } },
    { id:641, category:"Service & Pairing", q:"How do you approach wine selection for a corporate dinner where you don't know guests' preferences?", a:"Default to crowd-pleasing but quality-driven selections. For white: unoaked or lightly oaked Chardonnay or Sauvignon Blanc (Sancerre, Pouilly-Fumé, or New Zealand Marlborough — broadly appealing, food-versatile). For red: Pinot Noir (low tannin, fruit-forward — widest palate appeal) or medium-bodied Merlot/Cabernet blend. Avoid: very tannic, highly oxidative, or funky natural wines. Offer a sparkling option as aperitif. Always include a non-alcoholic option presented with equal care.", ref:null },
    { id:642, category:"Tasting", q:"Describe the systematic approach to identifying Sancerre vs. New Zealand Marlborough Sauvignon Blanc in a blind tasting.", a:"Sancerre (Loire): flint/gunflint/chalk minerality, green citrus (lime/grapefruit), herbal (grass, nettle), restrained aromatics, medium body, high acidity, steely dry finish, lower alcohol (~12.5%). Marlborough NZ: more explosive/pungent aromatics (passion fruit, capsicum, gooseberry, 'cat's pee' from thiols), tropical fruit forward, higher alcohol (~13%), less mineral, more aromatic intensity. Key tells: Sancerre = restraint + flint; Marlborough = pungency + tropical. Both high acid but NZ is more obviously aromatic.", ref:{ type:"search", label:"Sancerre vs Marlborough SB", url:"https://www.wine-searcher.com/find/sancerre+sauvignon+blanc" } },
    { id:643, category:"Regions", q:"Describe the wine regions and key producers of the Northern Rhône Valley in detail.", a:"Northern Rhône: Côte-Rôtie (Syrah ± Viognier co-fermentation; Côte Blonde = elegant, Côte Brune = tannic; Guigal La La wines). Condrieu (100% Viognier; Château-Grillet = monopole). Saint-Joseph (Syrah reds, Marsanne/Roussanne whites; largest appellation by volume). Crozes-Hermitage (largest, surrounds Hermitage; good value). Hermitage (granite hill; Jaboulet La Chapelle, Chave, Chapoutier Le Pavillon). Cornas (100% Syrah; most tannic/rustic; Auguste Clape, Thierry Allemand). Saint-Péray (whites only; Marsanne, some sparkling).", ref:{ type:"map", label:"Northern Rhône map", url:"https://www.wine-searcher.com/regions/rhone" } },
    { id:644, category:"Viticulture", q:"What is 'coulure' and 'millerandage' and how do they differ in their impact on wine quality?", a:"Coulure: poor fruit set — flowers fail to develop into berries due to cold/wet weather at flowering or vine nutritional imbalance (excess vigor). Results in very low yields (clusters with gaps). Millerandage ('hen and chicks'): uneven berry development producing a mix of full-sized and very small seedless berries (shot berries) on the same cluster. Coulure = pure yield loss with little quality benefit. Millerandage = yield loss + potential quality gain — the tiny shot berries have very high sugar concentration and flavor intensity, so moderate millerandage is prized in Champagne and Barolo.", ref:null },
    { id:645, category:"Vinification", q:"What is 'carbonic maceration' vs. 'semi-carbonic maceration' and how do they differ technically?", a:"True carbonic maceration: whole uncrushed clusters placed in a sealed CO₂-filled tank. Intracellular fermentation begins inside intact berries, producing glycerol, malic acid degradation, and primary fruit esters. Only possible at small scale. Semi-carbonic maceration (Beaujolais standard): clusters piled into a tank — bottom clusters are crushed by the weight above, beginning conventional fermentation; CO₂ produced rises and saturates the top clusters, which undergo intracellular fermentation. Result: ultra-fruity, low-tannin, banana/bubble-gum/kirsch aromas — classic Beaujolais Nouveau style.", ref:null },
    { id:646, category:"Regions", q:"Describe the key wine regions, soils, and styles of the Willamette Valley sub-AVAs.", a:"Dundee Hills: ancient Jory volcanic soils (iron-rich basalt) — benchmark earthy, structured Pinot Noir with red fruit and iron minerality (Domaine Drouhin, Adelsheim, Archery Summit). Eola-Amity Hills: windiest sub-AVA (Van Duzer Corridor gap), coolest, highest acidity/structure (Cristom, Bethel Heights). Ribbon Ridge: all Willakenzie sedimentary soils — silky, elegant Pinot (Beaux Frères, Brick House). Chehalem Mountains: diverse soils, highest elevation. McMinnville: marine sedimentary, can be powerful. Yamhill-Carlton: Willakenzie clay-silt — structured, age-worthy.", ref:{ type:"map", label:"Willamette Valley sub-AVAs", url:"https://www.wine-searcher.com/regions/willamette-valley" } },
    { id:647, category:"Grapes & Varieties", q:"Describe the sensory profile, key regions, and aging trajectory of Riesling across styles.", a:"Young dry Riesling (Mosel Kabinett): lime/green apple/slate, piercing acidity, low alcohol (8–9% abv), delicate. Young Alsace GC Riesling: more body, citrus/peach, mineral. Aged Riesling (10+ years): petrol/kerosene (TDN compound), honey/dried apricot, toast, still retaining acidity. Off-dry Spätlese: apricot/peach/honey, acidity keeps freshness. TBA: syrup-thick, saffron/honey/dried fruits. Riesling never loses its spine of acidity regardless of sweetness level — this is the defining characteristic that separates it from all other aromatic white varieties.", ref:{ type:"search", label:"Aged Riesling bottles", url:"https://www.wine-searcher.com/find/riesling+mosel+aged" } },
    { id:648, category:"Tasting", q:"How do you approach identifying a Southern Rhône GSM blend vs. an Australian GSM blend in a blind tasting?", a:"Southern Rhône (Châteauneuf-du-Pape, Gigondas): pale ruby-garnet, garrigue (lavender, wild thyme, rosemary), red fruit (kirsch, raspberry), white pepper, orange peel, high alcohol (14.5%+), low tannin, warm and generous. Australian GSM (McLaren Vale, Barossa): deeper color, riper dark fruit (blackberry, plum), more chocolate and spice, fuller body, higher alcohol, often American oak influence (vanilla/coconut). Key differentiators: garrigue = Southern Rhône; darker/riper fruit + more obvious oak = Australia. Both warm, generous, and Grenache-dominant.", ref:null },
    { id:649, category:"Labels & Law", q:"Explain the Italian DOC/DOCG system and the concept of 'Super Tuscans' as IGT wines.", a:"Italy's DOC/DOCG regulations specify permitted grape varieties, minimum aging, maximum yields, and geographic boundaries. Super Tuscans arose in the 1970s–80s when producers like Antinori (Tignanello — Sangiovese/Cabernet Sauvignon) and Marchese Incisa (Sassicaia — Cabernet Sauvignon/Cabernet Franc) used varieties or methods not permitted under DOC rules. Classified as simple Vino da Tavola or IGT (Indicazione Geografica Tipica — the catch-all geographic designation). Sassicaia eventually earned its own DOC in 1994. Today, Bolgheri DOC covers many Super Tuscans. IGT Toscana remains the most common classification.", ref:{ type:"search", label:"Super Tuscan bottles", url:"https://www.wine-searcher.com/find/super+tuscan+sassicaia+ornellaia" } },
    { id:650, category:"Service & Pairing", q:"What are the key principles of pairing wine with vegetarian and vegan tasting menus?", a:"Vegetarian dishes often feature umami-rich ingredients (mushrooms, tomatoes, aged cheeses, soy, miso, fermented foods) and varied textures. Principles: match intensity (light vegetable dishes = crisp whites; hearty root vegetable/legume dishes = medium reds). Umami in mushroom dishes: aged white Burgundy, earthy Pinot Noir, or Sherry (oxidative wines share savory compounds). Herb-dominant dishes: herbal whites (Sauvignon Blanc, Grüner Veltliner, Vermentino). Spiced dishes: off-dry Riesling or Gewurztraminer. Avoid: very tannic reds without protein to soften them — tannin + no meat fat = amplified astringency.", ref:null },
    { id:651, category:"Regions", q:"Describe the wine styles, grape varieties, and key estates of Stellenbosch, South Africa.", a:"Stellenbosch is South Africa's most prestigious wine district, producing the country's benchmark Cabernet Sauvignon and Bordeaux-style blends. Diverse soils: Hutton (red structured clay — Simonsberg), Clovelly (well-drained sandy loam), decomposed granite (Helderberg). Key estates: Kanonkop (Pinotage and Cabernet — Paul Sauer Bordeaux blend, old-vine Pinotage), Meerlust (Rubicon — iconic Bordeaux blend), Rust en Vrede, Waterford, Tokara, Jordan. Vergelegen (exceptional Bordeaux blends, Sauvignon Blanc). Stellenbosch Mountain sub-district: higher elevation, cooler, more structured wines.", ref:{ type:"map", label:"Stellenbosch wine map", url:"https://www.wine-searcher.com/regions/stellenbosch" } },
    { id:652, category:"Tasting", q:"How do you identify Viognier vs. Roussanne vs. Marsanne in a blind tasting of Northern Rhône whites?", a:"Viognier (Condrieu): explosive floral aromatics (honeysuckle, peach blossom, violet), stone fruit (peach, apricot), full body, low acidity, slightly oily texture, ginger/spice. Roussanne: more herbal (sage, thyme, chamomile), pear/apricot, higher acidity than Marsanne, floral but less intense than Viognier, elegant. Marsanne: fuller-bodied, low acid, almond/marzipan/beeswax when young; develops extraordinary hazelnut/honey/quince complexity with 10+ years age. Key: Viognier = most aromatic/floral; Marsanne = fullest-bodied/lowest-acid; Roussanne = most aromatic of the two Rhône whites but with better acidity.", ref:null },
    { id:653, category:"Viticulture", q:"What is 'wind stress' in viticulture and how do specific regions use or manage it?", a:"Wind stress causes stomata (leaf pores) to close, reducing photosynthesis and potentially slowing ripening. Excessive wind can physically damage shoots and flowers, reducing yield. However, moderate wind improves: air circulation (reducing fungal disease risk), transpiration cooling (preventing excessive heat buildup), and encourages deeper root development. Mistral (Rhône Valley): violent northerly wind that rapidly dries out vineyards after rain — critical disease prevention. Tramontane (Languedoc): similar effect. Eola-Amity Hills (Oregon): Van Duzer Corridor wind gap creates the region's distinctively high-acid, structured Pinot Noir.", ref:null },
    { id:654, category:"Regions", q:"Describe the key wine districts, varieties, and styles of Mendoza, Argentina in detail.", a:"Mendoza sits at the foot of the Andes (600–1,500m altitude). Sub-regions: Luján de Cuyo (Maipú, Agrelo, Perdriel) — historic Malbec heartland, structured, classic. Valle de Uco (Tupungato, Tunuyán, San Carlos) — high altitude (950–1,500m), cooler, more elegant Malbec, Cabernet Franc, Chardonnay. Maipú — warmer, some old-vine Malbec (Zuccardi, Clos de los Siete). Patagonia (Neuquén) — southernmost, very cool, Pinot Noir and Malbec. Key producers: Achaval Ferrer, Clos de los Siete, Zuccardi Valle de Uco, Catena Zapata (Adrianna Vineyard — world-class single vineyard).", ref:{ type:"map", label:"Mendoza sub-regions map", url:"https://www.wine-searcher.com/regions/mendoza" } },
    { id:655, category:"Vinification", q:"Explain the concept of 'whole-cluster fermentation' and the specific effect on Pinot Noir.", a:"Whole-cluster fermentation includes stems in the fermentation. The contribution depends on stem ripeness: green stems → harsh vegetal tannins (negative). Brown/woody ripe stems → spice (black pepper, cedar), structure, and complexity (positive). For Pinot Noir: whole-cluster adds: savory/earthy dimension, aromatic lift (from carbonic activity in intact berries), firmer tannin backbone for aging, reduced color (stems absorb anthocyanins). Advocates: much of top Burgundy (DRC, Rousseau use varying percentages). Critics argue it can overwhelm Pinot's delicate fruit if stems not perfectly ripe. Percentage used ranges from 0% to 100%.", ref:null },
    { id:656, category:"Tasting", q:"How do you approach identifying Sangiovese from Tuscany vs. a domestic California or Washington Sangiovese?", a:"Tuscan Sangiovese (Chianti Classico, Brunello): high acidity, high tannin, sour cherry/dried cherry/tomato leaf/leather, earthy/mineral, medium-full body, pronounced bitter almond on finish, ages dramatically. New World Sangiovese (CA, WA): riper fruit (black cherry, plum), lower acidity, softer tannins, more obvious oak, less structural tension, early drinking. Key tells: Tuscany = sour cherry + tomato leaf + bitterness; New World = riper fruit + rounder tannins + less complexity. Brunello specifically: more concentrated, broader, tar/tobacco, needs 10+ years.", ref:{ type:"search", label:"Chianti Classico Gran Selezione bottles", url:"https://www.wine-searcher.com/find/chianti+classico+gran+selezione" } },
    { id:657, category:"Regions", q:"Describe the wine styles and key appellations of Roussillon (southern France).", a:"Roussillon (Pyrénées-Orientales) borders Spain and has a hot, dry Mediterranean climate strongly influenced by the Tramontane wind. Soils: slate/schist (Maury, Banyuls), granite, limestone, and alluvial galets. Key styles: Vins Doux Naturels (fortified sweet wines) — Maury (Grenache Noir, rich, chocolate/dried fruit), Banyuls (Grenache, chocolate-pairing classic, also Banyuls Rancio — oxidative). Dry table wines: Côtes du Roussillon Villages (GSM blends, Carignan), increasingly serious. Collioure: coastal appellation sharing Banyuls geography but dry wines. Key producers: Domaine de la Rectorie, Mas Amiel, Gauby.", ref:{ type:"map", label:"Roussillon wine map", url:"https://www.wine-searcher.com/regions/roussillon" } },
    { id:658, category:"Service & Pairing", q:"How would you approach wine service for a table of guests where one is pregnant, one is a recovering alcoholic, and two are serious wine collectors?", a:"Professionalism and discretion are paramount. For the pregnant guest: present the non-alcoholic list with equal care — quality sparkling water, premium juice, or sophisticated NA options (Seedlip, Proxies, Noughty sparkling). Never draw attention to the choice. For the recovering alcoholic: quietly ask if they'd like non-alcoholic suggestions; present the same NA options without any comment or judgment. For the collectors: engage enthusiastically, ask about preferences, make confident recommendations at their level. The sommelier's goal is that every guest at the table feels equally well cared for and comfortable.", ref:null },
    { id:659, category:"Viticulture", q:"Explain the role of mycorrhizal fungi in vineyard soil health and vine nutrition.", a:"Mycorrhizal fungi form symbiotic relationships with vine roots, extending the root system's effective reach by 100–1,000x through a network of fine fungal threads (hyphae). The vine provides sugars; the fungi provide: water and nutrient access (especially phosphorus, which roots alone cannot access efficiently), drought resilience, and protection from soil pathogens. Synthetic fertilizers (especially phosphorus) destroy mycorrhizal networks. Organic and biodynamic viticulture actively encourages mycorrhizal health through: compost addition, cover crops, reduced tillage, and avoiding synthetic inputs. Healthy mycorrhizal networks are associated with genuine terroir expression.", ref:null },
    { id:660, category:"Regions", q:"Describe the key wine styles, producers, and geography of Barossa Valley and McLaren Vale.", a:"Barossa Valley: warm, flat valley floor (Marananga, Greenock, Seppeltsfield) with oldest Shiraz vines in the world (National Vineyard Register — some 150+ years). Style: rich, opulent, full-bodied Shiraz — dark fruit, chocolate, licorice, mocha, American oak (coconut/vanilla traditional). Key producers: Penfolds (Grange), Henschke (Hill of Grace — single vineyard Shiraz national treasure), Torbreck, Turkey Flat. McLaren Vale (coastal, south of Adelaide): Mediterranean climate, ironstone/sandy soils, old-vine Grenache and Shiraz. Style: more herb/chocolate/olive on Shiraz vs Barossa; Grenache: red fruit/garrigue. Producers: d'Arenberg, Coriole, Wirra Wirra.", ref:{ type:"map", label:"Barossa/McLaren Vale map", url:"https://www.wine-searcher.com/regions/barossa-valley" } },
    { id:661, category:"Tasting", q:"How does the Advanced CMS exam differ from the Certified exam in terms of blind tasting expectations?", a:"Certified: identify broad category (Old vs New World, variety group), basic structural components, and major regional style. Advanced: expected to identify specific grape variety, country of origin, specific region/appellation, and vintage within ±2 years for 60%+ of wines in a flight of 6 (2 whites, 2 reds, 1 sparkling or rosé). Must demonstrate command of the full deductive grid with precise terminology. Advanced candidates must also pass a theory exam (full global wine knowledge) and a service practical. Passing rate is approximately 30–35%. Preparation requires daily structured blind tasting for 1–2 years minimum.", ref:null },
  ],
  cs4: [
    { id:701, category:"Tasting", q:"Name and describe the key structural components assessed in Master Sommelier blind tasting.", a:"1) Acidity (spine of white wines). 2) Tannin (structure/ageability in reds). 3) Alcohol (body/weight). 4) Sweetness (residual sugar). 5) Body (overall weight on palate). 6) Finish (length and quality of aftertaste). Integration and balance across all components.", ref:null },
    { id:702, category:"Regions", q:"Describe the key quality factors distinguishing Premier Cru from Grand Cru sites in Burgundy.", a:"Grand Cru: ideal mid-slope position, optimal drainage and sun exposure, specific soil composition (limestone and marl), minimal frost risk. Premier Cru: good but slightly sub-optimal expression of site. Grand Cru shows more concentration, depth, and ageability.", ref:{ type:"map", label:"Burgundy Premier/Grand Cru map", url:"https://www.burgundy-report.com/maps/" } },
    { id:703, category:"Viticulture", q:"Explain the impact of rootstock selection on vine performance and wine quality.", a:"Phylloxera-resistant rootstocks (American hybrids) are used universally. Selection affects: vigor (SO4=high, 101-14=low), drought tolerance, soil adaptation (limestone-loving: 41B), ripening timing. Wrong rootstock can cause over-vigor, diluting fruit concentration.", ref:null },
    { id:704, category:"Vinification", q:"Describe the traditional method (Méthode Champenoise) in detail.", a:"1) Base wine production. 2) Assemblage (blending). 3) Liqueur de Tirage (yeast+sugar added). 4) Secondary fermentation in bottle. 5) Extended lees aging (NV min 15mo, Vintage min 36mo). 6) Riddling (remuage). 7) Disgorgement. 8) Dosage. 9) Corking and caging.", ref:{ type:"search", label:"Grower Champagne producers", url:"https://www.wine-searcher.com/find/grower+champagne" } },
    { id:705, category:"Service & Pairing", q:"Explain the bridge ingredient concept in advanced food and wine pairing.", a:"A bridge ingredient in a dish connects it to a wine by sharing flavor compounds (terpenes, thiols, etc.). E.g., lemon in a dish bridges to high-acid Chablis; mushrooms bridge to earthy Burgundy; char on steak bridges to smoky/tannic Cabernet. Used to engineer successful pairings for complex cuisine.", ref:null },
    { id:706, category:"Regions", q:"Compare and contrast the terroir and wine styles of Hermitage vs. Côte-Rôtie in the Northern Rhône.", a:"Hermitage: granite hill, Syrah (Marsanne/Roussanne for whites), rich/powerful, full-bodied, long-lived. Côte-Rôtie: Côte Brune (iron-rich soil, tannic, dark fruit) + Côte Blonde (sandy, more perfumed/floral). Viognier co-fermented in Côte-Rôtie for aromatic lift. More elegant vs. Hermitage's power.", ref:{ type:"map", label:"Northern Rhône map", url:"https://www.guildsomm.com/public_content/features/articles/b/blakeford/posts/northern-rhone" } },
    { id:707, category:"Tasting", q:"Describe the MS-level deductive approach to identifying a wine's vintage within 2 years.", a:"Assess color evolution (garnet/brick rim indicates age), aromatic development (tertiary vs. primary), tannin polymerization (silky vs. grippy), fruit freshness vs. dried character, and acid integration. Cross-reference with regional vintage knowledge. Key vintages: Burgundy 2010/2015/2019; Barolo 2010/2013/2016; Bordeaux 2005/2009/2010/2015/2016.", ref:null },
    { id:708, category:"Regions", q:"Describe the Wachau's three quality classifications and their requirements.", a:"Steinfeder (lightest, max 11.5% abv — named for feather grass). Federspiel (medium, 11.5–12.5% abv — named for falconer's lure). Smaragd (richest, min 12.5% abv — named for local emerald lizard; comparable to Alsace Grand Cru richness). All wines must be bone dry. Governed by the Vinea Wachau producers' association.", ref:{ type:"map", label:"Wachau map", url:"https://www.wine-searcher.com/regions/wachau" } },
    { id:709, category:"Viticulture", q:"Explain the role of Brettanomyces in wine — when is it a fault vs. a character?", a:"Brett is a spoilage yeast producing volatile phenols: 4-ethylphenol (barnyard, leather, band-aid), 4-ethylguaiacol (smoke, clove, spice). At low levels in traditionally made wines (old-vine Burgundy, Rhône, Rioja): adds complexity. At high levels: fault — overwhelms fruit and structure. Controlled by SO2 management, cellar hygiene, and barrel selection.", ref:null },
    { id:710, category:"Vinification", q:"Describe the production and styles of Madeira wine.", a:"Fortified wine from Madeira island. Unique estufagem process: heating wine (45–50°C) in tanks for 3+ months, or canteiro (naturally warm warehouse aging in barrel). Styles by grape/sweetness: Sercial (driest), Verdelho, Bual (Boal), Malmsey (sweetest). All have high acidity + oxidative character. Virtually indestructible — centennial bottles still remarkable.", ref:{ type:"search", label:"Madeira wine bottles", url:"https://www.wine-searcher.com/find/madeira+wine" } },
    { id:711, category:"Regions", q:"Describe Champagne's prestige cuvées and what distinguishes them from NV.", a:"Prestige Cuvées (Tête de Cuvée): made only in exceptional declared vintages from the best Grand Cru plots. Extended lees aging (often 6–10+ years). Examples: Dom Pérignon (Moët), Cristal (Roederer), La Grande Dame (Veuve Clicquot), Krug Grande Cuvée. Higher price, limited production, greater complexity and ageability vs. NV.", ref:{ type:"search", label:"Prestige Champagne cuvées", url:"https://www.wine-searcher.com/find/prestige+champagne" } },
    { id:712, category:"Tasting", q:"How do you approach blind tasting a white Burgundy vs. a New World Chardonnay at MS level?", a:"Burgundy: pale-medium lemon gold, restrained nose (apple, citrus, wet stone, brioche), high acidity, medium body, mineral/saline finish, integrated oak (if any), regional specificity (Chablis = flint; Meursault = hazelnut). New World Chardonnay: deeper gold, riper/tropical fruit, more oak-forward (vanilla/toast), lower acidity, fuller/creamier body, obvious MLF. Vintage and specific site narrow it further.", ref:null },
    { id:713, category:"Service & Pairing", q:"Design a wine pairing for a Kaiseki multi-course Japanese dinner.", a:"Junmai Daiginjo sake (opener — umami harmony). Premier Cru Chablis with sashimi (saline mineral + raw fish). Aged white Burgundy with abalone/tofu (richness + soy). Aged Champagne with tempura (effervescence cuts oil). Gevrey-Chambertin Pinot Noir with duck breast (earthy gaminess). Tokaji Aszú 5 puttonyos with wagashi sweets (sweet/savory contrast).", ref:null },
    { id:714, category:"Regions", q:"Describe the geology of Champagne and its influence on wine style.", a:"Champagne's subsoil is predominantly Belemnite chalk (Cretaceous limestone) — excellent drainage, high water retention in deep reserves, ideal calcium/alkalinity balance. The chalk gives characteristic finesse and fine bubbles. Upper layers vary: Montagne de Reims (clay, Pinot Noir), Côte des Blancs (pure chalk, Chardonnay), Vallée de la Marne (clay-chalk, Meunier).", ref:{ type:"map", label:"Champagne geology map", url:"https://www.champagne.fr/en/champagne-vineyard/champagne-viticultural-zones/map" } },
    { id:715, category:"Viticulture", q:"What is millerandage and how does it affect wine quality?", a:"Millerandage is uneven berry set where some berries remain small and seedless (shot berries) alongside normal-sized berries. Caused by cold/wet weather at flowering. Results in uneven ripening and reduced yield. However, the small shot berries concentrate sugars and flavors dramatically — can actually enhance quality when moderate (Champagne, Barolo).", ref:null },
    { id:716, category:"Vinification", q:"Explain the concept of assemblage in Champagne and its purpose.", a:"Assemblage is the blending process at the heart of Champagne production: blending different grape varieties (Chardonnay, Pinot Noir, Meunier), different villages/crus, and different vintages (reserve wines). Purpose: achieve a consistent house style year after year, compensate for vintage variation, and build complexity through layering. Dom Pérignon uses only one vintage — a constraint requiring exceptional raw material.", ref:null },
    { id:717, category:"Regions", q:"Describe Rioja Gran Reserva aging requirements and typical flavor profile.", a:"Minimum 5 years aging: at least 2 years in oak + 3 years in bottle before release. Profile: complex tertiary aromas — dried cherry/cranberry, aged leather, tobacco, balsamic/cedar, coconut/vanilla (American oak), dried herbs. Silky, integrated tannins from extended aging. Hallmark wines: CVNE Imperial GR, La Rioja Alta 904, Marqués de Murrieta Castillo Ygay.", ref:{ type:"search", label:"Rioja Gran Reserva bottles", url:"https://www.wine-searcher.com/find/rioja+gran+reserva" } },
    { id:718, category:"Tasting", q:"How do you use the grid in MS exam conditions — describe the process under time pressure?", a:"You have 25 minutes for 6 wines. Structure every wine identically. Sight: 15 seconds. Nose: 45–60 seconds (fruit, earth, oak, development). Palate: 45–60 seconds (structure, then conclusion). Conclusion: state grape, country, region, appellation, vintage — commit with confidence. Examiners reward logical reasoning even if the conclusion is wrong. Never skip structural analysis to guess early.", ref:null },
    { id:719, category:"Labels & Law", q:"Explain the Burgundy négociant system vs. domaine bottling and its quality implications.", a:"Négociant (merchant): buys grapes, must, or finished wine from growers and produces under their own label. Quality ranges from industrial to exceptional (Leroy, DRC owns vineyards as a domaine). Domaine bottling (estate): grower makes and bottles their own wine — increased since the 1970s, seen as more authentic terroir expression. Maison vs. Domaine debate is central to Burgundy's identity.", ref:null },
    { id:720, category:"Regions", q:"Describe the key wine producers and styles of the Willamette Valley, Oregon.", a:"Willamette Valley AVA: maritime-influenced, cool climate. Sub-AVAs: Dundee Hills (red Jory volcanic soil — benchmark Pinot Noir), Eola-Amity Hills (windiest, highest acid/structure), Ribbon Ridge (Sedimentary Willakenzie — silky Pinot). Key producers: Domaine Drouhin Oregon, Adelsheim, Eyrie Vineyards, Elk Cove, Ponzi. Style: earthy, red-fruited, Burgundian frame with distinct Oregon character.", ref:{ type:"map", label:"Willamette Valley map", url:"https://www.wine-searcher.com/regions/willamette-valley" } },
    { id:721, category:"Service & Pairing", q:"How do you assess and recommend wine for a high-net-worth guest with a 500+ per bottle budget?", a:"Ask open questions: occasion (celebration vs. contemplative dinner), food (chef's menu or à la carte), preferences (Old World elegance vs. power), prior favorites. At that level, offer: Burgundy Grand Cru (DRC, Leroy, Rousseau), Bordeaux First Growth, aged Barolo (Giacomo Conterno), Grower Champagne (Krug, Selosse), aged white Burgundy (Raveneau, Coche-Dury). Provide context: terroir, vintage, aging potential. Never oversell; build trust.", ref:null },
    { id:722, category:"Tasting", q:"Describe the MS approach to identifying Sauternes vs. German TBA in a blind tasting.", a:"Sauternes (Semillon/Sauvignon Blanc/Muscadelle): deep gold, botrytis aromas (honey, dried apricot, saffron, ginger), thick viscous texture, marmalade, balanced acidity. German TBA (Riesling): extreme sweetness and acidity in tension, petrol/mineral, apricot/peach, very low alcohol, electrifying acidity cutting through sweetness. TBA = more acid tension; Sauternes = more body and Botrytis-forward richness.", ref:{ type:"search", label:"Sauternes top estates", url:"https://www.wine-searcher.com/find/sauternes+premier+cru" } },
    { id:723, category:"Regions", q:"Describe the geography, soils, and key wines of Barossa Valley vs. Eden Valley.", a:"Barossa Valley (low altitude ~280m): warm, rich alluvial soils, old-vine Shiraz (Penfolds, Henschke Hill of Grace, Torbreck) — powerful, full-bodied, plummy/chocolate. Eden Valley (high altitude ~400–500m): cooler, harder soils, world-class Riesling (Henschke, Hewitson) and elegant Shiraz — more structured, floral, peppery. The two valleys share a GI but are climatically distinct.", ref:{ type:"map", label:"Barossa/Eden Valley map", url:"https://www.wine-searcher.com/regions/barossa-valley" } },
    { id:724, category:"Viticulture", q:"Explain what 'hang time' means and the trade-offs involved.", a:"Hang time refers to extended time on the vine post-optimal ripeness. Benefits: additional physiological ripeness, softening of tannins, development of tertiary flavors. Risks: loss of acidity (deacidification), elevated sugar/alcohol, potential for raisining, increased disease risk. Common in warm-climate winemaking (California, Australia). Contrasted with cool-climate harvesting at peak natural acidity.", ref:null },
    { id:725, category:"Service & Pairing", q:"How does a Master Sommelier approach a table that has ordered a red Burgundy with fish?", a:"Never correct the guest — their preference is paramount. Present the wine graciously and professionally. If the guest is open to dialogue, gently note that the wine's earthiness may complement certain fish preparations. Recommend a sauce or preparation (mushroom-based, truffle) that could bridge the pairing. Offer to adjust course order if possible. The sommelier's role is to enhance the experience, not impose orthodoxy.", ref:null },
    { id:726, category:"Labels & Law", q:"Explain the Italian DOC system's approach to 'Superiore' and 'Classico' designations.", a:"Classico: applies to wines from the historic, original heartland of an appellation — generally higher quality, older vines (Chianti Classico DOCG, Valpolicella Classico, Soave Classico). Superiore: wines that meet higher standards — minimum alcohol level, lower yields, and sometimes extended aging requirements (Valpolicella Superiore, Montepulciano d'Abruzzo Colline Teramane). Both indicate elevated quality within the broader appellation.", ref:null },
    { id:727, category:"Tasting", q:"Describe the MS-level approach to identifying Grüner Veltliner vs. Sauvignon Blanc in a blind tasting.", a:"Both: high acidity, herbaceous notes. Grüner Veltliner: white pepper (hallmark), grapefruit/lemon/apple, green herbs (less aggressive than SB), mineral, medium-full body, often slight textural weight, lower aromatic intensity than SB. Sauvignon Blanc: more aggressive/pungent green aromas (capsicum, nettles, cat's pee, gooseberry/passion fruit), lighter body, sharper acidity. GV = more restrained and peppery; SB = more overtly aromatic and herbaceous.", ref:null },
    { id:728, category:"Regions", q:"Describe the vineyards and key producers of Vosne-Romanée and why it is considered Burgundy's greatest village.", a:"Vosne-Romanée contains the highest concentration of Grand Cru vineyards in Burgundy: Romanée-Conti (1.8 ha — world's most expensive wine), La Tâche (6 ha), Richebourg (8 ha), La Romanée, Romanée-Saint-Vivant, Grands Échézeaux, Échézeaux. Premier Crus: Les Malconsorts, Cros Parantoux (Méo-Camuzet/Henri Jayer). DRC, Méo-Camuzet, Anne Gros are key producers. The village benchmark for Pinot Noir complexity, depth, and longevity.", ref:{ type:"map", label:"Vosne-Romanée map", url:"https://www.burgundy-report.com/maps/" } },
    { id:729, category:"Viticulture", q:"Explain the concept of 'terroir expression' vs. 'winemaker's signature' and the ongoing debate.", a:"Terroir expression: the wine communicates the unique character of its specific site — soil, climate, topography — above all else. Winemaker's signature: stylistic choices (new oak, micro-oxygenation, extraction level, filtration) imprint the wine with a consistent house style that may override or minimize site differences. Great wine ideally achieves both. The debate centers on: should wine be transparent to place or shaped by human craft? Both produce great wine; the tension defines modern viticulture.", ref:null },
    { id:730, category:"Vinification", q:"Describe the production of Vin Jaune from the Jura region of France.", a:"Vin Jaune (yellow wine) is made from Savagnin grapes in the Château-Chalon or Côtes du Jura appellations. After fermentation, wine ages in previously used 228L barrels for a minimum of 6 years and 3 months WITHOUT topping up. A veil of yeast (voile — similar to Sherry flor) forms on the surface. The result: nutty, oxidative wine (walnut, dried fruit, curry spice) of extraordinary longevity. Sold in the distinctive 62cl clavelin bottle.", ref:{ type:"search", label:"Vin Jaune bottles", url:"https://www.wine-searcher.com/find/vin+jaune+chateau+chalon" } },
    { id:731, category:"Service & Pairing", q:"How do you approach wine pairing for a tasting menu with 10+ courses?", a:"Work with the kitchen in advance. Map the flavor arc: light → rich → sweet. Key principles: each wine must be able to stand alone as well as complement its course. Use half-pours to manage alcohol progression. Build in a palette-cleansing sparkling or high-acid wine mid-meal. Consider: one wine per 2–3 courses to avoid overwhelming guests. End with fortified or sweet wine. Total alcohol should not exceed the equivalent of roughly one bottle per person across the meal.", ref:null },
    { id:732, category:"Tasting", q:"Describe the MS-level approach to identifying Nebbiolo (Barolo) vs. aged Bordeaux in a blind tasting.", a:"Nebbiolo/Barolo: garnet with pronounced orange rim (even young), very high tannin and acidity, tar/roses/leather/dried red fruit, angular structure, never fully loses its grip. Aged Bordeaux (Cabernet dominant): deeper garnet with red/amber rim, cedar/graphite/tobacco/cassis/leather, tannins soften to velvet, more body, gentler finish. Key tells: Nebbiolo's orange rim and tar/roses are unmistakable; Bordeaux's cedar/graphite and more body/weight differentiate. Vintage and region narrow further.", ref:null },
    { id:733, category:"Regions", q:"Describe the key wine regions and indigenous varieties of Greece.", a:"Greece has one of the world's oldest wine traditions. Key regions: Santorini (volcanic island — Assyrtiko: bone dry, high acid, saline, mineral; grown in basket-trained 'kouloura' vines). Naoussa (northern Greece — Xinomavro: high acid, high tannin, dried red fruit, often compared to Nebbiolo/Barolo). Nemea (Peloponnese — Agiorgitiko/'St. George': softer, plummy reds). Muscat of Samos (sweet fortified). Greek wine is gaining serious international recognition.", ref:{ type:"map", label:"Greek wine regions", url:"https://www.wine-searcher.com/regions/greece" } },
    { id:734, category:"Viticulture", q:"Explain the concept of 'hydraulic lift' in vine physiology and its role in drought tolerance.", a:"Hydraulic lift is the process by which deep vine roots draw water up from water tables at night and release it into the surrounding soil, where shallower roots can access it during the day. This allows established vines to survive drought conditions that would kill other plants. It is one reason old vines (with deep root systems) produce better-quality fruit during drought years than young vines, and why dry-farmed old vines are so prized.", ref:null },
    { id:735, category:"Vinification", q:"Describe the process and purpose of 'cold settling' (débourbage) in white winemaking.", a:"After pressing, white grape juice contains suspended solids (grape pulp, skin fragments, seed particles) called gross lees. Cold settling (débourbage) chills the juice to 5–10°C for 12–24 hours, causing these solids to settle to the bottom of the tank. The clarified juice is then racked off and fermentation begins. Purpose: reduces harsh, bitter, and cooked flavors from solids while preserving delicate aromatic compounds. Too much clarification, however, can strip body and complexity.", ref:null },
    { id:736, category:"Service & Pairing", q:"How does a Master Sommelier approach training junior sommeliers in blind tasting?", a:"Structured daily blind tasting is non-negotiable — ideally 3–6 wines per day. Use the deductive grid every time, never skip steps. Build a 'library' of benchmark wines (Chablis, white Burgundy, Sancerre, Barolo, Rioja, Hermitage). Teach by elimination: if not Pinot, why not? If Old World, what tells? Emphasize structure over fruit (fruit descriptions are subjective; acidity, tannin, and body are more reliable). Weekly debriefs, recorded notes, vintage tracking. The exam tests reasoning, not guessing.", ref:null },
    { id:737, category:"Tasting", q:"Describe the MS-level approach to identifying Chenin Blanc from the Loire Valley vs. South Africa in a blind tasting.", a:"Loire Chenin (Vouvray, Savennières, Montlouis): chamomile/hay/quince/beeswax, high acidity, medium body, often off-dry or sweet, mineral/flint finish, lower alcohol. South African Chenin ('Steen'): richer stone fruit (peach, guava), broader body, higher alcohol, less angular acidity, more approachable in youth, often oaked. Old-vine SA Chenin (Swartland — Sadie, Mullineux): more complex, can rival Loire. Key tells: Loire = more linear acid, chamomile, restraint; SA = richer, tropical fruit, rounder.", ref:{ type:"search", label:"South African Chenin Blanc bottles", url:"https://www.wine-searcher.com/find/south+africa+chenin+blanc" } },
    { id:738, category:"Regions", q:"Describe the key crus and styles of Beaujolais, distinguishing them from Beaujolais Nouveau.", a:"Beaujolais Nouveau: released third Thursday of November, carbonic maceration, ultra-fruity, meant to be drunk immediately — a marketing phenomenon, not a quality statement. The 10 Crus are entirely different: Morgon (earthy, structured, ages 10+ years), Moulin-à-Vent (most powerful, 'king'), Fleurie (feminine, floral), Chénas, Juliénas, Chiroubles, Régnié, Côte de Brouilly, Brouilly, Saint-Amour. All 100% Gamay on granite/schist soils. Top producers: Marcel Lapierre, Jean Foillard, Guy Breton, Château Thivin.", ref:{ type:"map", label:"Beaujolais crus map", url:"https://www.wine-searcher.com/regions/beaujolais" } },
    { id:739, category:"Viticulture", q:"Explain the role of 'phenolic ripeness' in relation to seed ripeness and how a winemaker assesses it at harvest.", a:"Seed ripeness is the key indicator of phenolic maturity — seeds must be brown (not green), hard, and taste nutty/woody rather than green/bitter. Green seeds release harsh, unripe tannins during fermentation regardless of sugar levels. A winemaker assesses: seed color and taste (must be brown/nutty), skin texture (should be soft and easily broken), stem lignification (woody stems = physiologically ripe). In warm climates, sugar races ahead of seed ripeness — this is why adding water or picking early is sometimes necessary.", ref:null },
    { id:740, category:"Vinification", q:"Describe the process and wine style of Banyuls and Maury (French Vins Doux Naturels).", a:"Banyuls (Roussillon, on the Spanish border) and Maury are fortified wines (Vins Doux Naturels — naturally sweet wines) made primarily from Grenache Noir. Fermentation is stopped by adding grape spirit (mutage) when desired residual sugar is achieved. Banyuls styles: young (Rimage — fresh, fruity), oxidative (Tuilé/Ambré — rancio notes from barrel aging exposed to heat and oxygen, deliberately oxidative). Grenache's natural affinity with chocolate makes Banyuls one of the rare red wines that pairs with dark chocolate.", ref:{ type:"search", label:"Banyuls / Maury bottles", url:"https://www.wine-searcher.com/find/banyuls" } },
    { id:741, category:"Service & Pairing", q:"How do you handle a situation at the MS exam where you are uncertain about a wine's identity?", a:"Never guess blindly or panic. Work through your deductions systematically and commit to a logical conclusion supported by evidence. State what you know with confidence: 'The high acidity, translucent ruby color, and forest floor/red cherry profile point to a cool-climate Pinot Noir. The restraint and minerality suggest Old World, most likely Burgundy, potentially a village or Premier Cru level wine, drinking around 8–12 years of age.' Examiners score your reasoning process — a well-argued wrong answer outscores a right answer with no explanation.", ref:null },
    { id:742, category:"Tasting", q:"Describe the MS deductive approach to identifying Riesling vs. Grüner Veltliner vs. Chablis in a blind tasting of three white wines.", a:"Riesling: high acidity, low-medium alcohol, petrol/TDN (aged), lime/slate, often slightly sweet even when labeled dry, linear and precise. Grüner Veltliner: white pepper (hallmark), grapefruit/celery/green herb, medium-full body, dry, rarely shows petrol. Chablis (Chardonnay): pale gold, flint/gunflint/oyster shell, green apple, lemon curd, NO pepper, NO petrol, oak absent or minimal, higher body than Riesling. Key differentiators: pepper = GV; petrol = Riesling; flint + apple + no distinctive spice = Chablis.", ref:null },
    { id:743, category:"Regions", q:"Describe the key vineyard sites, producers, and styles of Gevrey-Chambertin.", a:"Gevrey-Chambertin is the largest and most powerful village in the Côte de Nuits. Grand Crus: Chambertin and Chambertin-Clos de Bèze (the most powerful and structured of the group); Charmes-Chambertin (most approachable); Mazis-Chambertin; Latricières-Chambertin; Griotte-Chambertin; Chapelle-Chambertin; Ruchottes-Chambertin; Mazoyères-Chambertin. Benchmark Premier Crus: Clos Saint-Jacques (often Grand Cru quality), Les Cazetiers, Lavaux Saint-Jacques. Top producers: Rousseau, Dugat-Py, Denis Mortet, Fourrier, Trapet.", ref:{ type:"map", label:"Gevrey-Chambertin map", url:"https://www.burgundy-report.com/maps/" } },
    { id:744, category:"Viticulture", q:"What is 'deficit irrigation' and how does it improve wine quality in warm climates?", a:"Deficit irrigation deliberately applies water below the vine's full needs during specific growth stages to induce mild stress. During berry development: slight water deficit slows berry enlargement, producing smaller berries with higher skin-to-juice ratios — more color, tannin, and flavor per liter. During ripening: regulated deficit halts excess vegetative growth (shoots stop growing), directing energy to fruit development. Used in Napa, Barossa, Mendoza, and McLaren Vale. Forbidden in most EU appellations (irrigation often prohibited or restricted).", ref:null },
    { id:745, category:"Vinification", q:"Explain 'spinning cone column' and 'reverse osmosis' as modern alcohol adjustment tools.", a:"Spinning Cone Column (SCC): wine passes down a spinning column, separating aromatic compounds (collected and saved), then alcohol is removed from the stripped wine, then the aromatics are added back. Produces natural-tasting lower-alcohol wines. Reverse Osmosis (RO): wine is forced through a semi-permeable membrane under pressure, separating water and alcohol from flavor compounds; alcohol is removed from the permeate and water is returned to the wine. Both are used to correct overripe/high-alcohol wines and are controversial — banned in many traditional European appellations.", ref:null },
    { id:746, category:"Tasting", q:"How do you distinguish Barolo from Barbaresco in a blind MS tasting using only structural and aromatic clues?", a:"Both are 100% Nebbiolo. Barolo (Serralunga/Monforte d'Alba): typically more powerful, broader-shouldered tannin, deeper color, more tar/earth/iron, needs longer aging (5+ years minimum, 15–20 ideal). Barbaresco (Neive/Treiso): more approachable, finer-grained tannins, more floral (rose/violet), red fruit forward, earlier drinking (3–8 years). However, La Morra Barolo can be as elegant as Barbaresco. Always note: if Nebbiolo is confirmed, use alcohol (Barolo tends 14–15%, Barbaresco 13.5–14%), body (Barolo fuller), and tannin coarseness to differentiate.", ref:{ type:"search", label:"Barolo vs Barbaresco bottles", url:"https://www.wine-searcher.com/find/barolo+barbaresco" } },
    { id:747, category:"Regions", q:"Describe the terroir and wine styles of Pomerol and why Pétrus commands such prices.", a:"Pomerol is a tiny Right Bank Bordeaux appellation (800 ha) with no official classification. The most valued sites sit on a clay-and-iron plateau (crasse de fer/iron-rich clay) that retains moisture perfectly for Merlot. Pétrus (11.4 ha): sits on the 'blue clay' centre of the plateau — unique iron-rich clay produces extraordinary concentration, velvety tannins, truffle/plum/mocha complexity. Annual production ~3,000 cases — scarcity + quality = price. No second label. Harvested in one afternoon when conditions are perfect. Managed by Christian Moueix.", ref:{ type:"map", label:"Pomerol map", url:"https://www.wine-searcher.com/regions/pomerol" } },
    { id:748, category:"Service & Pairing", q:"Describe the MS approach to building a complete by-the-glass program for a fine dining restaurant.", a:"BTG wines must represent the full spectrum of the food menu. Framework: 2–3 sparkling (NV Champagne house, Grower Champagne, Crémant or quality Prosecco); 3–4 whites (unoaked crisp, aromatic, oaked/rich, dessert/half-pour); 2–3 rosé depending on season; 4–5 reds (light/Pinot, medium/Rhône or Sangiovese, full/Cabernet, structured/age-worthy); 1–2 fortified/dessert. Rotate 25–30% seasonally. Margin typically 3–4× cost. Feature at least one sommelier value pick and one splurge option per category.", ref:null },
    { id:749, category:"Regions", q:"Describe the key Champagne villages and their classification as Grand Cru and Premier Cru.", a:"Champagne's Échelle des Crus ('ladder of growths') rates villages 80–100%: Grand Cru villages (100%): 17 total including Aÿ (Pinot Noir), Ambonnay (Pinot Noir), Cramant (Chardonnay), Avize (Chardonnay), Le Mesnil-sur-Oger (Chardonnay — Blanc de Blancs benchmark, home of Krug Clos du Mesnil and Salon), Verzy, Verzenay (Montagne de Reims). Premier Cru (90–99%): 42 villages. Grand Cru fruit commands the highest purchase prices and appears on prestige cuvée labels.", ref:{ type:"map", label:"Champagne village classification", url:"https://www.wine-searcher.com/regions/champagne" } },
    { id:750, category:"Vinification", q:"What is the difference between 'fining' and 'filtration' and the arguments for and against each?", a:"Fining: adding a substance (bentonite, egg white, gelatin, isinglass, casein) that binds to unwanted particles and settles out — primarily removes proteins (heat instability), harsh tannins, and some color. Gentle but can strip wine of body and aromatic compounds. Filtration: passing wine through a filter medium (pad, membrane, cross-flow) to physically remove particles and microorganisms. Sterile filtration ensures microbiological stability for mass-market wines. Arguments against both: 'unfined, unfiltered' proponents argue they strip texture, mouthfeel, and terroir expression. Top Burgundy domaines (DRC, Leroy) minimize both.", ref:null },
    { id:751, category:"Tasting", q:"Explain 'reduction' vs. 'oxidation' as winemaking faults — how to detect each in a blind tasting.", a:"Reduction: wine has not been exposed to enough oxygen during winemaking. Aromas: struck match, rubber, rotten egg, onion, garlic (from H2S and mercaptans). Positive micro-reduction in some styles (Mosel Riesling, Muscadet) adds complexity. Fix: splash decanting, aeration. Oxidation: excessive oxygen exposure. Aromas: bruised apple, sherry-like, flat, nutty, caramelized. Color: browning in whites, tawny/brick in reds, loss of freshness. A fault in table wines; intentional in Sherry, Madeira, Jura Vin Jaune. Reduction and oxidation sit at opposite ends of the oxygen management spectrum.", ref:null },
    { id:752, category:"Regions", q:"Describe the key wine regions, grapes, and styles of the Finger Lakes AVA at MS level.", a:"The Finger Lakes (upstate New York) is defined by 11 glacial lakes whose thermal mass moderates the harsh continental climate. Seneca Lake (deepest, warmest) and Cayuga Lake are the most important. Benchmark varieties: Riesling (Dr. Konstantin Frank, Hermann J. Wiemer, Red Newt — from bone dry to TBA-equivalent botrytized styles, rivaling German quality). Cabernet Franc (increasingly serious, especially around Seneca Lake). Chardonnay, Gewurztraminer, and hybrid varieties (Traminette, Marquette) also produced. The region is definitively America's finest Riesling source.", ref:{ type:"map", label:"Finger Lakes wine map", url:"https://www.wine-searcher.com/regions/finger-lakes" } },
    { id:753, category:"Viticulture", q:"Explain the physiology of Botrytis cinerea infection and why only certain conditions produce noble rot vs. grey rot.", a:"Botrytis cinerea spores are universally present in vineyards. Noble rot requires two distinct phases: Phase 1 — morning mist or humidity (>90% RH) allows spore germination and penetration of the grape skin. Phase 2 — warm, dry, sunny afternoons arrest further Botrytis spread while causing water evaporation through the punctured skin, concentrating sugars (up to 300+ g/L), glycerol, and flavor compounds. Grey rot: continuous humidity without the drying phase allows uncontrolled Botrytis spread, destroying the berry. Sauternes' proximity to the Ciron River (cold tributary creating morning mists on the Garonne) creates the perfect microclimate.", ref:null },
    { id:754, category:"Vinification", q:"Describe the production of Vintage Champagne and what distinguishes a declared vintage year.", a:"Vintage Champagne is produced only in years a house 'declares' — typically 3–5 times per decade when quality is exceptional. Unlike NV, no reserve wines are blended in; 100% of wine is from the stated vintage. Minimum aging on lees: 36 months (vs. 15 for NV). Disgorgement adds dosage (typically lower than NV — 6–8 g/L). The wine continues to age in bottle post-disgorgement. Great Champagne vintages: 2002, 2004, 2008, 2012, 2015, 2018, 2019. Vintage Champagne shows greater depth, precision, and ageability than NV — peak drinking often 10–20 years post-harvest.", ref:{ type:"search", label:"Vintage Champagne bottles", url:"https://www.wine-searcher.com/find/vintage+champagne+2008" } },
    { id:755, category:"Service & Pairing", q:"How should a Master Sommelier approach pairing wine with a traditional French cheese course featuring 5 different cheeses?", a:"Design for the arc of cheeses rather than individual pairings. Structure: Fresh/chèvre (Sancerre, Pouilly-Fumé — acid mirrors acid, regional pairing). Soft-ripened Brie/Camembert (white Burgundy, aged Champagne — richness + effervescence). Washed-rind Époisses or Munster (Alsatian Gewurztraminer or Pinot Gris — spice and weight match pungency; regional Burgundy red also works). Aged Comté/Gruyère (Jura Savagnin or aged white Burgundy — nutty mirrors nutty). Roquefort/Bleu (Sauternes or Banyuls — classic sweet/salty contrast). Serve whites before moving to any reds for the table.", ref:null },
    { id:756, category:"Regions", q:"Describe the production and styles of Vintage Port vs. Single Quinta Port and how to distinguish them.", a:"Vintage Port (VP): produced only in declared vintages (unanimous approval by major shippers); blended from multiple quintas across the Douro. Aged 2 years in cask, then minimum 10–15 years in bottle (peak 20–40 years). Forms heavy sediment — must decant. Single Quinta Vintage Port (SQVP): from one specific estate; produced in good but undeclared years (e.g., Quinta do Vesúvio, Quinta do Crasto). Often earlier drinking than blended VP. Distinguishing in a tasting: both show intense ruby-purple (young), dried fruit, dark chocolate, pepper, high alcohol (20–21%). Age assessment: color evolution from purple to brick/tawny rim, tertiary complexity.", ref:{ type:"search", label:"Vintage Port top estates", url:"https://www.wine-searcher.com/find/vintage+port+quinta" } },
    { id:757, category:"Tasting", q:"How do you approach identifying a wine as 'natural wine' in an MS blind tasting, and is it a legitimate category?", a:"Natural wines may show: slight haze or cloudiness (unfined/unfiltered), slight effervescence in still wines (refermentation), orange/amber hue (skin contact whites), volatile acidity (VA) elevated but controlled, Brett (barnyard) at varying levels, lower SO2 (more oxidative evolution), and unusual aromatic profiles. In an exam: if a wine seems 'faulty' but has internal logic and balance, consider natural wine. For the MS exam, assess structural components first — the conclusion should still place the wine geographically. 'Natural wine' is not an exam conclusion but an observation. The category has no legal definition.", ref:null },
    { id:758, category:"Regions", q:"Compare the terroir and wine styles of Margaux vs. Pauillac on the Médoc Left Bank.", a:"Margaux (southernmost of the Médoc's famous communes): gravelly soils with more clay/sand admixture. Produces Bordeaux's most perfumed, feminine Left Bank wines — floral (violet, rose), cassis, cedar, silky tannins. Benchmark: Château Margaux (1er Cru), Palmer (often outperforms classification), Rauzan-Ségla. Pauillac (further north, most concentrated): deep gravel on ridges, excellent drainage, warmest. Produces Bordeaux's most powerful, structured wines — pure cassis, graphite/pencil lead, high tannin, firm backbone, exceptional ageability. Three 1er Crus: Lafite Rothschild, Latour, Mouton Rothschild.", ref:{ type:"map", label:"Médoc communes map", url:"https://www.wine-searcher.com/regions/medoc" } },
    { id:759, category:"Viticulture", q:"What is 'clonal selection' and how has it affected the diversity (and uniformity) of major varieties like Chardonnay and Pinot Noir?", a:"Clonal selection involves propagating a single vine's cuttings repeatedly, selecting for desirable traits (yield, disease resistance, ripening time). The Dijon clones for Pinot Noir (113, 114, 115, 667, 777) and Chardonnay (76, 95, 96) transformed New World viticulture from the 1980s onward — replacing older heat-treated Californian and Australian selections with high-quality Burgundian clones. Trade-off: clonal uniformity produces wines with consistent character but potentially less complexity than old-vine massale selections. Modern best practice blends multiple clones in the vineyard for diversity.", ref:null },
    { id:760, category:"Vinification", q:"Describe the production of Colheita Tawny Port and how it differs from aged Tawny blends.", a:"Colheita is a single-vintage Tawny Port that must be aged in small oak casks for a minimum of 7 years (most are aged 20–40+ years) before bottling. The vintage year and bottling date must appear on the label. Unlike blended 10/20/30/40-year Tawny (which averages age across multiple vintages using a solera-like system), Colheita preserves vintage character alongside the oxidative Tawny style: walnut, dried orange peel, caramel, coffee, and rancio. Top Colheita producers: Niepoort, Barros, Burmester. Must be consumed within 1–2 years of bottling as oxidative wines decline rapidly once opened.", ref:{ type:"search", label:"Colheita Tawny Port bottles", url:"https://www.wine-searcher.com/find/colheita+port" } },
    { id:761, category:"Service & Pairing", q:"Describe the MS-level approach to pairing wine with a tasting menu built around Japanese A5 Wagyu beef.", a:"A5 Wagyu's extraordinary marbling (intramuscular fat scoring 8–12 BMS) demands a wine that cuts through intense richness without overwhelming the delicate umami sweetness. Best approaches: Aged white Burgundy (Corton-Charlemagne or Meursault — oxidative richness + acidity cuts fat, shares umami resonance). Aged red Burgundy (Gevrey-Chambertin Grand Cru — earthy, iron, light enough not to overpower). High-acid Barolo (Serralunga — tannin grip + tar cuts fat; must be aged 15+ years for tannin integration). Avoid: New World Cabernet (tannin + fat = metallic/astringent), heavily oaked wines. Portion size and cooking method (tataki vs. teppanyaki) also influence selection.", ref:null },
  ],
};

